import React, { lazy, Suspense, useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { createRoot } from 'react-dom/client'
import ReactMarkdown from 'react-markdown'
import type { AgentEvent, AppPreferences, ChangeReceipt, ChangeReceiptDetail, ChangeReceiptSummary, ComplianceResult, HistoryPolicy, ParrotAudit, ParrotAuditKey, ParrotDraftInput, ParrotIssue, ParrotOptimizeEvent, ParrotOptimizeTarget, ParrotStatus, DecisionRecord, DiffContent, ProjectFileContent, ProjectFileEntry, ProjectRecord, ProviderInput, ProviderProfile, ReceiptDrift, SnapshotPolicy, SnapshotStorage, SnapshotSummary, TaskMode, TaskPolicy, TaskRecord, UpdateInfo } from '../shared/types'
import type { AppearanceSettings } from '../shared/types'
import { PROVIDER_PRESETS as RAW_PROVIDER_PRESETS } from '../shared/types'
import { DEFAULT_APPEARANCE } from '../shared/appearance'
import { appendAgentEvents, conversationEvents, taskConversation } from '../shared/events'
import { languageFromLocale } from '../shared/locale'
import { shouldSubmitPrompt } from '../shared/input'
import logoUrl from '../logo.png'
import { TerminalView } from './components/TerminalView'
import { languageForFile } from './fileLanguage'
import './style.css'
import './style-extras.css'

type View='projects'|'parrot'|'workspace'|'receipts'|'snapshots'|'decisions'|'settings'
type SettingsSection='general'|'appearance'|'providers'|'snapshots'
const blankProvider:ProviderInput={name:'',protocol:'openai-chat',baseUrl:'',model:'',apiKey:'',thinkingEnabled:false,reasoningEffort:'high',maxContext:128000,taskBudget:16000,timeoutMs:120000,inputPricePerMillion:0,outputPricePerMillion:0}
const blankDraft:ParrotDraftInput={name:'',goals:'',audience:'',features:'',nonGoals:'',stack:'',commands:'',constraints:''}
const SIDEBAR_COLLAPSED_STORAGE_KEY='crazyparrot.sidebar-collapsed'
let language=languageFromLocale(navigator.languages?.[0]??navigator.language)
const tr=(zh:string,en:string)=>language==='zh'?zh:en
function applyLanguagePreference(preference:AppPreferences['language']):void { language=preference==='system'?languageFromLocale(navigator.languages?.[0]??navigator.language):preference;document.documentElement.lang=language==='zh'?'zh-CN':'en' }
const auditItemLabel=(key:ParrotAuditKey)=>key==='sections'?tr('章节完整性','Sections'):key==='quality'?tr('内容质量','Content quality'):key==='commands'?tr('命令可执行性','Commands'):key==='protection'?tr('保护力度','Protection'):tr('测试要求','Testing')
const providerPresets=()=>RAW_PROVIDER_PRESETS.map(p=>({...p,name:language==='en'&&p.id==='custom-openai'?'Custom OpenAI-compatible':language==='en'&&p.id==='custom-anthropic'?'Custom Anthropic-compatible':p.name}))
const LazyMonacoEditor=lazy(async()=>({default:(await import('./components/MonacoEditor')).MonacoEditor}))
const LazyMonacoDiff=lazy(async()=>({default:(await import('./components/MonacoEditor')).MonacoDiff}))

type CodeEditorProps={value:string;language:string;readOnly?:boolean;onChange?:(value:string)=>void;className?:string;ariaLabel?:string}
type CodeDiffProps={original:string;modified:string;language:string;className?:string}
function MonacoEditor(props:CodeEditorProps){return <Suspense fallback={<div className={`${props.className??''} monaco-loading`}>{tr('正在加载编辑器…','Loading editor…')}</div>}><LazyMonacoEditor {...props}/></Suspense>}
function MonacoDiff(props:CodeDiffProps){return <Suspense fallback={<div className={`${props.className??''} monaco-loading`}>{tr('正在加载比较器…','Loading diff…')}</div>}><LazyMonacoDiff {...props}/></Suspense>}

function App():React.JSX.Element {
  const [view,setView]=useState<View>('projects');const [projects,setProjects]=useState<ProjectRecord[]>([]);const [archivedProjects,setArchivedProjects]=useState<ProjectRecord[]>([]);const [project,setProject]=useState<ProjectRecord|null>(null)
  const [parrot,setParrot]=useState<ParrotStatus|null>(null);const [providers,setProviders]=useState<ProviderProfile[]>([]);const [tasks,setTasks]=useState<TaskRecord[]>([]);const [sidebarCollapsed,setSidebarCollapsed]=useState(()=>{try{return localStorage.getItem(SIDEBAR_COLLAPSED_STORAGE_KEY)==='1'}catch{return false}});const [appearance,setAppearance]=useState<AppearanceSettings>({...DEFAULT_APPEARANCE});const [settingsSection,setSettingsSection]=useState<SettingsSection>('general');const [preferences,setPreferences]=useState<AppPreferences>({language:'system'});const [,setLanguageRevision]=useState(0)
  const [events,setEvents]=useState<Record<string,AgentEvent[]>>({});const [snapshots,setSnapshots]=useState<SnapshotSummary[]>([]);const [notice,setNotice]=useState('')
  const pendingEventsRef=useRef<AgentEvent[]>([]);const eventFlushTimerRef=useRef<number|null>(null)
  const refresh=useCallback(async()=>{const [ps,archived,ms,ss]=await Promise.all([window.crazyParrot.projects.list(),window.crazyParrot.projects.listArchived(),window.crazyParrot.providers.list(),window.crazyParrot.snapshots.list()]);setProjects(ps);setArchivedProjects(archived);setProviders(ms);setSnapshots(ss)},[])
  useEffect(()=>{void refresh();const flush=()=>{eventFlushTimerRef.current=null;const pending=pendingEventsRef.current.splice(0);if(!pending.length)return;setEvents(old=>{const next={...old};const byTask=new Map<string,AgentEvent[]>();for(const event of pending){const events=byTask.get(event.taskId)??[];events.push(event);byTask.set(event.taskId,events)}for(const [taskId,taskEvents] of byTask)next[taskId]=appendAgentEvents(next[taskId]??[],taskEvents);return next});if(project&&pending.some(event=>['evidence','error','status','approval'].includes(event.type)))void window.crazyParrot.tasks.list(project.id).then(setTasks)};const unsubscribe=window.crazyParrot.onAgentEvent(event=>{pendingEventsRef.current.push(event);if(eventFlushTimerRef.current===null)eventFlushTimerRef.current=window.setTimeout(flush,80)});return()=>{unsubscribe();if(eventFlushTimerRef.current!==null){window.clearTimeout(eventFlushTimerRef.current);flush()}}},[refresh,project])
  useEffect(()=>{void window.crazyParrot.appearance.get().then(setAppearance).catch(()=>{})},[])
  useEffect(()=>{void window.crazyParrot.app.preferences().then(value=>{setPreferences(value);applyLanguagePreference(value.language);setLanguageRevision(revision=>revision+1)}).catch(()=>{})},[])
  useEffect(()=>{document.documentElement.dataset.theme=appearance.theme;let style=document.getElementById('crazyparrot-custom-css') as HTMLStyleElement|null;if(!style){style=document.createElement('style');style.id='crazyparrot-custom-css';document.head.append(style)}style.textContent=appearance.customCss;window.dispatchEvent(new Event('crazyparrot-theme-change'))},[appearance])
  useEffect(()=>{try{localStorage.setItem(SIDEBAR_COLLAPSED_STORAGE_KEY,sidebarCollapsed?'1':'0')}catch{}},[sidebarCollapsed])
  const openProject=async(p:ProjectRecord)=>{setProject(p);const [c,t]=await Promise.all([window.crazyParrot.parrot.status(p.id),window.crazyParrot.tasks.list(p.id)]);const history=await Promise.all(t.map(async task=>[task.id,await window.crazyParrot.tasks.events(task.id)] as const));setParrot(c);setTasks(t);setEvents(old=>({...old,...Object.fromEntries(history)}));setView(c.approved?'workspace':'parrot')}
  const choose=async(mode:'new'|'import')=>{try{const path=await window.crazyParrot.projects.chooseDirectory(mode);if(!path)return;const p=await window.crazyParrot.projects.add(path);await refresh();await openProject(p)}catch(e){showError(e,setNotice)}}
  const archiveProject=async(item:ProjectRecord)=>{if(!window.confirm(tr(`归档“${item.name}”？项目源文件不会被改动。`,`Archive “${item.name}”? Its source files will not be changed.`)))return;try{await window.crazyParrot.projects.archive(item.id);if(project?.id===item.id){setProject(null);setParrot(null);setTasks([]);setEvents({});setView('projects')}await refresh();setNotice(tr('项目已归档，可随时恢复。','Project archived. You can restore it at any time.'))}catch(error){showError(error,setNotice)}}
  const restoreProject=async(item:ProjectRecord)=>{try{await window.crazyParrot.projects.restore(item.id);await refresh();setNotice(tr('项目已恢复到项目列表。','Project restored to the project list.'))}catch(error){showError(error,setNotice)}}
  const removeProject=async(item:ProjectRecord)=>{if(!window.confirm(tr(`从 CrazyParrot 移除“${item.name}”？只会删除本地索引、任务记录和快照，不会删除项目文件。`,`Remove “${item.name}” from CrazyParrot? This removes only local records, task history, and snapshots—not project files.`)))return;try{await window.crazyParrot.projects.remove(item.id);await refresh();setNotice(tr('已从 CrazyParrot 移除项目记录。','Project record removed from CrazyParrot.'))}catch(error){showError(error,setNotice)}}
  const changeView=(v:View)=>{setView(v)}
  const openSettings=(section:SettingsSection='general')=>{setSettingsSection(section);setView('settings')}
  const changePreferences=(value:AppPreferences)=>{setPreferences(value);applyLanguagePreference(value.language);setLanguageRevision(revision=>revision+1)}
  const appearanceStyle={'--appearance-image':appearance.backgroundUrl?`url(${JSON.stringify(appearance.backgroundUrl)})`:'none','--appearance-image-opacity':String(appearance.backgroundOpacity/100)} as React.CSSProperties
  return <div className={`app-shell ${sidebarCollapsed?'sidebar-collapsed':''} ${appearance.backgroundUrl?'has-background':''}`} style={appearanceStyle}>
    <div className="appearance-background" aria-hidden="true"/>
    <header className="titlebar"><div className="traffic-space"/><div className="brand"><img className="brand-logo" src={logoUrl} alt=""/><span>CrazyParrot</span></div><button className="sidebar-toggle" onClick={()=>setSidebarCollapsed(value=>!value)} aria-label={sidebarCollapsed?tr('展开侧边栏','Expand sidebar'):tr('收起侧边栏','Collapse sidebar')} title={sidebarCollapsed?tr('展开侧边栏','Expand sidebar'):tr('收起侧边栏','Collapse sidebar')}>{sidebarCollapsed?'›':'‹'}</button><div className="header-status"><span className={`dot ${providers.some(p=>p.verifiedAt)?'online':''}`}/>{providers.some(p=>p.verifiedAt)?tr('已连接','Connected'):tr('未连接','Not connected')}<button className="header-settings" onClick={()=>openSettings()} aria-label={tr('设置','Settings')} title={tr('设置','Settings')}>⚙</button></div></header>
    <aside className="sidebar">
      <Sidebar view={view} projects={projects} project={project} providers={providers} collapsed={sidebarCollapsed} onChangeView={changeView} onOpenSettings={openSettings} onChoose={choose} onOpenProject={openProject} onArchive={archiveProject}/>
    </aside>
    <main>{notice&&<div className="notice" role="alert"><span>{notice}</span><button onClick={()=>setNotice('')} aria-label={tr('关闭提示','Dismiss notification')}>×</button></div>}
      {view==='projects'&&<ProjectsView projects={projects} archivedProjects={archivedProjects} onChoose={choose} onOpen={openProject} onArchive={archiveProject} onRestore={restoreProject} onRemove={removeProject}/>} 
      {view==='parrot'&&project&&parrot&&<ParrotView project={project} status={parrot} providers={providers} onChange={setParrot} onApproved={()=>setView('workspace')} setNotice={setNotice}/>}
      {view==='workspace'&&project&&parrot&&<Workspace project={project} parrot={parrot} providers={providers} tasks={tasks} events={events} refreshTasks={()=>window.crazyParrot.tasks.list(project.id).then(setTasks)} setNotice={setNotice} editParrot={()=>setView('parrot')}/>} 
      {view==='receipts'&&<ReceiptsView project={project} setNotice={setNotice}/>} 
      {view==='snapshots'&&<SnapshotsView snapshots={snapshots} projects={projects} refresh={refresh} setNotice={setNotice}/>} 
      {view==='decisions'&&<DecisionsView project={project} editParrot={()=>setView('parrot')} setNotice={setNotice}/>} 
      {view==='settings'&&<SettingsView section={settingsSection} onSectionChange={setSettingsSection} appearance={appearance} onAppearanceChange={setAppearance} preferences={preferences} onPreferencesChange={changePreferences} providers={providers} snapshots={snapshots} refresh={refresh} setNotice={setNotice}/>} 
    </main>
  </div>
}

function Sidebar({view,projects,project,providers,collapsed,onChangeView,onOpenSettings,onChoose,onOpenProject,onArchive}:{view:View;projects:ProjectRecord[];project:ProjectRecord|null;providers:ProviderProfile[];collapsed:boolean;onChangeView:(view:View)=>void;onOpenSettings:(section:SettingsSection)=>void;onChoose:(mode:'new'|'import')=>void;onOpenProject:(project:ProjectRecord)=>Promise<void>;onArchive:(project:ProjectRecord)=>Promise<void>}){
  const [query,setQuery]=useState('');const [showAll,setShowAll]=useState(false);const [menuProjectId,setMenuProjectId]=useState<string|null>(null);const normalized=query.trim().toLocaleLowerCase();const matching=normalized?projects.filter(item=>`${item.name} ${item.path}`.toLocaleLowerCase().includes(normalized)):projects;const visible=showAll||normalized?matching:matching.slice(0,6);const connected=providers.filter(item=>item.verifiedAt).length
  const open=(item:ProjectRecord)=>{setQuery('');void onOpenProject(item)}
  return <><nav className="sidebar-nav"><Nav active={view==='projects'} onClick={()=>onChangeView('projects')} icon="⌂" label={tr('项目','Projects')} collapsed={collapsed}/><Nav active={view==='receipts'} onClick={()=>onChangeView('receipts')} icon="✓" label={tr('变更凭证','Receipts')} collapsed={collapsed}/><Nav active={view==='snapshots'} onClick={()=>onChangeView('snapshots')} icon="↶" label={tr('快照','Snapshots')} collapsed={collapsed}/><Nav active={view==='decisions'} onClick={()=>onChangeView('decisions')} icon="◇" label={tr('决策','Decisions')} collapsed={collapsed}/></nav><div className="sidebar-actions"><button className="sidebar-new" onClick={()=>onChoose('new')} title={tr('新建项目','New project')} aria-label={tr('创建项目','Create project')}><span>＋</span><b>{tr('新建项目','New project')}</b></button><button className="sidebar-import" onClick={()=>onChoose('import')} title={tr('导入项目','Import project')} aria-label={tr('导入项目','Import project')}><span>↗</span><b>{tr('导入','Import')}</b></button></div><section className="sidebar-projects"><div className="sidebar-section-head"><p>{tr('项目','Projects')}</p>{projects.length>6&&<button onClick={()=>setShowAll(value=>!value)} title={showAll?tr('仅显示最近项目','Show recent projects'):tr('显示所有项目','Show all projects')}>{showAll?'−':'+'}</button>}</div><label className="project-search"><span>⌕</span><input value={query} onChange={event=>setQuery(event.target.value)} placeholder={tr('搜索项目…','Search projects…')} aria-label={tr('搜索项目','Search projects')}/>{query&&<button onClick={()=>setQuery('')} aria-label={tr('清除搜索','Clear search')}>×</button>}</label><div className="project-list">{visible.map(item=><div key={item.id} className={`sidebar-project-row ${project?.id===item.id?'active':''}`}><button className="sidebar-project-open" onClick={()=>open(item)} title={item.path}><span className="sidebar-project-mark">{item.name.slice(0,1).toUpperCase()}</span><div><b>{item.name}</b><small>{item.parrotApprovedHash?item.hasGit?'Git · Parrot ✓':tr('Parrot 已确认','Parrot approved'):tr('需要完成 Parrot','Parrot required')}</small></div>{project?.id===item.id&&<i aria-label={tr('当前项目','Current project')}>●</i>}</button><button className="project-more" aria-label={tr(`管理 ${item.name}`,`Manage ${item.name}`)} onClick={()=>setMenuProjectId(value=>value===item.id?null:item.id)}>···</button>{menuProjectId===item.id&&<div className="project-menu"><button onClick={()=>{setMenuProjectId(null);void onArchive(item)}}>{tr('归档项目','Archive project')}</button></div>}</div>)}{!visible.length&&<div className="sidebar-project-empty">{normalized?tr('没有匹配的项目','No matching projects'):tr('尚未添加项目','No projects yet')}</div>}</div></section><div className="sidebar-footer"><button onClick={()=>onOpenSettings('providers')} className={connected?'ready':''} title={connected?tr('模型已连接','Models connected'):tr('配置模型','Configure models')}><span className={`dot ${connected?'online':''}`}/><div><b>{connected?tr(`${connected} 个模型可用`,`${connected} model${connected===1?'':'s'} ready`):tr('模型尚未配置','No model connected')}</b><small>{connected?tr('可在任务中使用','Available for tasks'):tr('前往设置','Open settings')}</small></div></button></div></>
}

function Nav(p:{active:boolean;onClick():void;icon:string;label:string;collapsed:boolean;badge?:number}){return <button className={p.active?'active':''} onClick={p.onClick} title={p.label}><span className="nav-icon">{p.icon}</span><b>{p.label}</b>{p.badge&&<i>{p.badge}</i>}</button>}

function ProjectsView({projects,archivedProjects,onChoose,onOpen,onArchive,onRestore,onRemove}:{projects:ProjectRecord[];archivedProjects:ProjectRecord[];onChoose:(m:'new'|'import')=>void;onOpen:(p:ProjectRecord)=>void;onArchive:(p:ProjectRecord)=>void;onRestore:(p:ProjectRecord)=>void;onRemove:(p:ProjectRecord)=>void}){
  return <section className="page projects-page"><div className="simple-page-head"><h1>{tr('项目','Projects')}</h1><div><button className="primary" onClick={()=>onChoose('new')}>＋ {tr('新建','New')}</button><button onClick={()=>onChoose('import')}>{tr('打开目录','Open folder')}</button></div></div>
    {projects.length>0?<div className="recent compact"><div className="project-grid">{projects.map(p=><article className="project-card" key={p.id}><button className="project-open" onClick={()=>void onOpen(p)}><div className="project-icon">{p.name.slice(0,2).toUpperCase()}</div><div><h3>{p.name}</h3><p>{p.path}</p><span className={p.parrotApprovedHash?'ready':'pending'}>{p.parrotApprovedHash?tr('就绪','Ready'):tr('待确认','Parrot required')}</span>{p.hasGit&&<span className="git">Git</span>}</div><i>→</i></button><button className="project-card-action" onClick={()=>onArchive(p)}>{tr('归档','Archive')}</button></article>)}</div></div>:<div className="empty-table">{tr('暂无项目','No projects')}</div>}
    {archivedProjects.length>0&&<section className="archived-projects"><div><h2>{tr('已归档项目','Archived projects')}</h2><small>{tr('归档不会修改项目文件；仅从侧栏隐藏。','Archiving only hides a project from the sidebar; its files remain untouched.')}</small></div>{archivedProjects.map(p=><article key={p.id}><div><b>{p.name}</b><small>{p.path}</small></div><button onClick={()=>onRestore(p)}>{tr('恢复','Restore')}</button><button className="danger-link" onClick={()=>onRemove(p)}>{tr('从 CrazyParrot 移除','Remove from CrazyParrot')}</button></article>)}</section>}
  </section>
}

function AppearanceView({settings,onChange,setNotice}:{settings:AppearanceSettings;onChange:(settings:AppearanceSettings)=>void;setNotice:(notice:string)=>void}){
  const [draft,setDraft]=useState<AppearanceSettings>(settings);const [busy,setBusy]=useState(false)
  useEffect(()=>setDraft(settings),[settings])
  const update=(patch:Partial<AppearanceSettings>)=>setDraft(current=>({...current,...patch}))
  const chooseBackground=async()=>{setBusy(true);try{const background=await window.crazyParrot.appearance.chooseBackground();if(background)update(background)}catch(error){showError(error,setNotice)}finally{setBusy(false)}}
  const clearBackground=()=>setDraft(({backgroundId:_backgroundId,backgroundUrl:_backgroundUrl,...current})=>current)
  const save=async()=>{setBusy(true);try{const {backgroundUrl:_backgroundUrl,...input}=draft;const saved=await window.crazyParrot.appearance.save(input);onChange(saved);setNotice(tr('外观设置已应用','Appearance applied'))}catch(error){showError(error,setNotice)}finally{setBusy(false)}}
  const reset=async()=>{setBusy(true);try{const saved=await window.crazyParrot.appearance.save({...DEFAULT_APPEARANCE});onChange(saved);setDraft(saved);setNotice(tr('已恢复默认外观','Default appearance restored'))}catch(error){showError(error,setNotice)}finally{setBusy(false)}}
  return <section className="page appearance-page"><div className="page-heading"><div><div className="eyebrow">{tr('偏好设置','Preferences')}</div><h1>{tr('外观','Appearance')}</h1><p>{tr('切换深浅主题，为界面添加背景，并用 CSS 微调每一个细节。','Switch between dark and light themes, add a background, and tune every detail with CSS.')}</p></div></div><div className="appearance-layout"><div className="appearance-controls"><section className="appearance-section"><div className="appearance-section-head"><div><span>{tr('主题','Theme')}</span><h2>{tr('黑白模式','Dark & light')}</h2></div></div><div className="theme-options"><button className={draft.theme==='dark'?'active':''} onClick={()=>update({theme:'dark'})} aria-pressed={draft.theme==='dark'}><i className="theme-swatch dark"/><b>{tr('黑色','Dark')}</b><small>{tr('专注、低亮度','Focused, low glare')}</small></button><button className={draft.theme==='light'?'active':''} onClick={()=>update({theme:'light'})} aria-pressed={draft.theme==='light'}><i className="theme-swatch light"/><b>{tr('白色','Light')}</b><small>{tr('清晰、高对比','Clear, high contrast')}</small></button></div></section><section className="appearance-section"><div className="appearance-section-head"><div><span>{tr('背景图片','Background image')}</span><h2>{draft.backgroundUrl?tr('已添加背景','Background added'):tr('使用你的图片','Use your image')}</h2></div>{draft.backgroundUrl&&<button className="text-button" onClick={clearBackground}>{tr('移除','Remove')}</button>}</div><div className="background-picker"><div className={`background-preview ${draft.backgroundUrl?'has-image':''}`} style={draft.backgroundUrl?{backgroundImage:`url(${JSON.stringify(draft.backgroundUrl)})`}:undefined}><span>{draft.backgroundUrl?'':tr('未选择图片','No image selected')}</span></div><div><button onClick={()=>void chooseBackground()} disabled={busy}>{draft.backgroundUrl?tr('更换图片','Replace image'):tr('选择图片','Choose image')}</button><small>{tr('支持 PNG、JPEG、WebP、GIF、BMP，最大 30 MB；图片会复制到本机应用数据中。','PNG, JPEG, WebP, GIF, BMP up to 30 MB. The image is copied to local app data.')}</small></div></div><label className="opacity-control"><div><span>{tr('背景透明度','Background opacity')}</span><output>{draft.backgroundOpacity}%</output></div><input type="range" min="0" max="100" value={draft.backgroundOpacity} onChange={event=>update({backgroundOpacity:Number(event.target.value)})} disabled={!draft.backgroundUrl} aria-label={tr('背景透明度','Background opacity')}/></label></section><section className="appearance-section"><div className="appearance-section-head"><div><span>{tr('自定义样式','Custom CSS')}</span><h2>{tr('覆盖应用样式','Override app styles')}</h2></div><button className="text-button" onClick={()=>update({customCss:''})} disabled={!draft.customCss}>{tr('清空','Clear')}</button></div><textarea className="custom-css" value={draft.customCss} onChange={event=>update({customCss:event.target.value})} maxLength={100000} spellCheck={false} aria-label={tr('自定义 CSS','Custom CSS')} placeholder={'.app-shell {\n  --ui-accent: #7c5cff;\n}\n\nbutton.primary {\n  border-radius: 999px;\n}'}/><small className="custom-css-hint">{tr('将在应用默认样式之后加载。修改会在点击“应用外观”后保存。','Loaded after the default app styles. Changes are saved when you apply the appearance.')}</small></section><div className="appearance-actions"><button onClick={()=>void reset()} disabled={busy}>{tr('恢复默认','Restore defaults')}</button><button className="primary" onClick={()=>void save()} disabled={busy}>{tr('应用外观','Apply appearance')}</button></div></div><aside className="appearance-preview-card"><div className="appearance-preview-stage" data-theme-preview={draft.theme} style={draft.backgroundUrl?{backgroundImage:`linear-gradient(rgba(0,0,0,${1-draft.backgroundOpacity/100}), rgba(0,0,0,${1-draft.backgroundOpacity/100})), url(${JSON.stringify(draft.backgroundUrl)})`}:undefined}><div className="preview-titlebar"><span/><b>CrazyParrot</b><i/></div><div className="preview-body"><div className="preview-sidebar"><span className="active"/><span/><span/><span/></div><div className="preview-content"><div className="preview-row"><b>{tr('正在进行的任务','Active task')}</b><i/></div><div className="preview-lines"><span/><span/><span/></div><div className="preview-button">{tr('继续','Continue')}</div></div></div></div><p>{tr('预览会在保存后应用到整个应用。','The preview is applied to the whole app after saving.')}</p></aside></div></section>
}

function SettingsView({section,onSectionChange,appearance,onAppearanceChange,preferences,onPreferencesChange,providers,snapshots,refresh,setNotice}:{section:SettingsSection;onSectionChange:(section:SettingsSection)=>void;appearance:AppearanceSettings;onAppearanceChange:(settings:AppearanceSettings)=>void;preferences:AppPreferences;onPreferencesChange:(preferences:AppPreferences)=>void;providers:ProviderProfile[];snapshots:SnapshotSummary[];refresh:()=>Promise<void>;setNotice:(notice:string)=>void}){
  const sections:Array<{id:SettingsSection;icon:string;label:string;description:string}>= [
    {id:'general',icon:'⚙',label:tr('通用','General'),description:tr('语言、预算、更新与诊断','Language, budgets, updates, diagnostics')},
    {id:'appearance',icon:'◐',label:tr('外观','Appearance'),description:tr('主题、背景与自定义样式','Theme, background, and CSS')},
    {id:'providers',icon:'◈',label:tr('模型','Models'),description:tr('模型连接与高级参数','Connections and model limits')},
    {id:'snapshots',icon:'↶',label:tr('快照策略','Snapshot policy'),description:tr('保留时间与存储空间','Retention and storage')}
  ]
  return <section className="page settings-hub"><div className="page-heading"><div><div className="eyebrow">{tr('应用偏好','Application preferences')}</div><h1>{tr('设置','Settings')}</h1><p>{tr('将全局配置集中管理；项目历史与工作内容仍保留在左侧。','Manage global preferences here; project history and work remain in the sidebar.')}</p></div></div><div className="settings-hub-layout"><nav className="settings-nav" aria-label={tr('设置分类','Settings sections')}>{sections.map(item=><button key={item.id} className={section===item.id?'active':''} onClick={()=>onSectionChange(item.id)}><span>{item.icon}</span><div><b>{item.label}</b><small>{item.description}</small></div><i>›</i></button>)}</nav><div className="settings-content">{section==='general'&&<GeneralSettingsView preferences={preferences} onPreferencesChange={onPreferencesChange} setNotice={setNotice}/>} {section==='appearance'&&<AppearanceView settings={appearance} onChange={onAppearanceChange} setNotice={setNotice}/>} {section==='providers'&&<ProvidersView providers={providers} refresh={refresh} setNotice={setNotice} embedded/>} {section==='snapshots'&&<SnapshotPolicyView snapshots={snapshots} refresh={refresh} setNotice={setNotice}/>}</div></div></section>
}

function GeneralSettingsView({preferences,onPreferencesChange,setNotice}:{preferences:AppPreferences;onPreferencesChange:(preferences:AppPreferences)=>void;setNotice:(notice:string)=>void}){
  const [taskPolicy,setTaskPolicy]=useState<TaskPolicy>({maxTotalTokens:200000,maxEstimatedCostUsd:0});const [historyPolicy,setHistoryPolicy]=useState<HistoryPolicy>({retentionDays:180});const [update,setUpdate]=useState<UpdateInfo|null>(null);const [busy,setBusy]=useState(false)
  useEffect(()=>{void Promise.all([window.crazyParrot.app.taskPolicy(),window.crazyParrot.app.historyPolicy()]).then(([task,history])=>{setTaskPolicy(task);setHistoryPolicy(history)}).catch(error=>showError(error,setNotice))},[setNotice])
  const changeLanguage=async(next:AppPreferences)=>{setBusy(true);try{const saved=await window.crazyParrot.app.savePreferences(next);onPreferencesChange(saved);setNotice(tr('语言设置已应用','Language preference applied'))}catch(error){showError(error,setNotice)}finally{setBusy(false)}}
  const savePolicies=async()=>{setBusy(true);try{const [task,history]=await Promise.all([window.crazyParrot.app.saveTaskPolicy(taskPolicy),window.crazyParrot.app.saveHistoryPolicy(historyPolicy)]);setTaskPolicy(task);setHistoryPolicy(history);setNotice(tr('任务与历史策略已保存','Task and history policies saved'))}catch(error){showError(error,setNotice)}finally{setBusy(false)}}
  const cleanup=async()=>{if(!confirm(tr(`删除 ${historyPolicy.retentionDays} 天前已完成的任务历史？此操作不可恢复。`,`Delete completed task history older than ${historyPolicy.retentionDays} days? This cannot be undone.`)))return;setBusy(true);try{const result=await window.crazyParrot.app.cleanupHistory();setNotice(tr(`已清理 ${result.removedTasks} 条任务历史与 ${result.reclaimedSnapshots} 个快照`,`Removed ${result.removedTasks} task records and ${result.reclaimedSnapshots} snapshots`))}catch(error){showError(error,setNotice)}finally{setBusy(false)}}
  const diagnostics=async()=>{setBusy(true);try{const result=await window.crazyParrot.app.exportDiagnostics();if(result)setNotice(tr('已导出脱敏诊断包','Redacted diagnostics exported'))}catch(error){showError(error,setNotice)}finally{setBusy(false)}}
  const checkUpdate=async()=>{setBusy(true);try{const result=await window.crazyParrot.app.checkForUpdates();setUpdate(result);if(result.available)setNotice(tr(`发现新版本 ${result.latestVersion}` ,`Update ${result.latestVersion} is available`));else if(!result.error)setNotice(tr('当前已是最新版本','You are on the latest version'))}catch(error){showError(error,setNotice)}finally{setBusy(false)}}
  return <section className="settings-panel general-settings"><div className="settings-panel-head"><div><span>{tr('通用','General')}</span><h2>{tr('语言、预算与维护','Language, budgets & maintenance')}</h2><p>{tr('这些设置只保存在当前电脑。诊断包不包含项目路径、提示词、源代码、API 地址或凭据。','These settings stay on this computer. Diagnostics exclude project paths, prompts, source code, API endpoints, and credentials.')}</p></div></div><section className="settings-block"><h3>{tr('界面语言','Interface language')}</h3><div className="choice-row">{([['system',tr('跟随系统','System')],['zh','简体中文'],['en','English']] as const).map(([value,label])=><button key={value} className={preferences.language===value?'active':''} aria-pressed={preferences.language===value} disabled={busy} onClick={()=>void changeLanguage({language:value})}>{label}</button>)}</div></section><section className="settings-block"><h3>{tr('每任务安全预算','Per-task safety budget')}</h3><div className="settings-fields"><label>{tr('Token 上限','Token limit')}<input type="number" min="10000" step="10000" value={taskPolicy.maxTotalTokens} onChange={event=>setTaskPolicy({...taskPolicy,maxTotalTokens:Number(event.target.value)||10000})}/></label><label>{tr('费用上限（USD，0 为关闭）','Cost limit (USD, 0 disables)')}<input type="number" min="0" step="0.1" value={taskPolicy.maxEstimatedCostUsd} onChange={event=>setTaskPolicy({...taskPolicy,maxEstimatedCostUsd:Number(event.target.value)||0})}/></label></div><small>{tr('达到上限时，任务会暂停并要求明确批准后才继续。费用估算需要在模型配置中填写单价。','When reached, a task pauses until explicitly approved. Cost estimates require prices in the model profile.')}</small></section><section className="settings-block"><h3>{tr('本地历史','Local history')}</h3><div className="settings-fields"><label>{tr('保留天数','Retention days')}<input type="number" min="1" max="3650" value={historyPolicy.retentionDays} onChange={event=>setHistoryPolicy({...historyPolicy,retentionDays:Number(event.target.value)||1})}/></label></div><div className="settings-actions"><button disabled={busy} onClick={()=>void cleanup()}>{tr('立即清理已过期历史','Clean expired history now')}</button><button className="primary" disabled={busy} onClick={()=>void savePolicies()}>{tr('保存策略','Save policies')}</button></div></section><section className="settings-block"><h3>{tr('更新与诊断','Updates & diagnostics')}</h3><div className="settings-actions"><button disabled={busy} onClick={()=>void checkUpdate()}>{tr('检查更新','Check for updates')}</button><button disabled={busy} onClick={()=>void diagnostics()}>{tr('导出脱敏诊断包','Export redacted diagnostics')}</button>{update?.available&&<button className="primary" onClick={()=>void window.crazyParrot.app.openReleasePage()}>{tr('打开下载页面','Open download page')}</button>}</div>{update&&<small className={update.error?'warning-text':''}>{update.error?tr(`无法检查更新：${update.error}`,`Could not check for updates: ${update.error}`):update.available?tr(`当前 ${update.currentVersion}，可更新到 ${update.latestVersion}`,`Current ${update.currentVersion}; ${update.latestVersion} is available`):tr(`当前版本 ${update.currentVersion} 已是最新`, `Version ${update.currentVersion} is current`)}</small>}</section></section>
}

function ParrotView({project,status,providers,onChange,onApproved,setNotice}:{project:ProjectRecord;status:ParrotStatus;providers:ProviderProfile[];onChange:(s:ParrotStatus)=>void;onApproved():void;setNotice:(s:string)=>void}){
  const [readme,setReadme]=useState(status.readme);const [agents,setAgents]=useState(status.agents);const [tab,setTab]=useState<'readme'|'agents'|'wizard'>(status.readme&&status.agents?'readme':'wizard');const [draft,setDraft]=useState({...blankDraft,name:project.name});const [busy,setBusy]=useState(false)
  const verified=providers.filter(p=>p.verifiedAt)
  const [optimizeProviderId,setOptimizeProviderId]=useState(verified[0]?.id??'');const [instruction,setInstruction]=useState('');const [optimizing,setOptimizing]=useState(false);const [optimizeReport,setOptimizeReport]=useState<{issues:ParrotIssue[];truncated:boolean}|null>(null)
  const [audit,setAudit]=useState<ParrotAudit|null>(null)
  const [liveCheck,setLiveCheck]=useState<{valid:boolean;issues:ParrotIssue[]}|null>(null)
  const [optimizeProgress,setOptimizeProgress]=useState<{chars:number;elapsedSec:number}|null>(null)
  const optimizingRef=useRef(false);const activeRunRef=useRef<string|null>(null);const targetRef=useRef<ParrotOptimizeTarget>('readme');const beforeRef=useRef('');const accRef=useRef('');const flushTimerRef=useRef<ReturnType<typeof setInterval>|null>(null);const elapsedTimerRef=useRef<ReturnType<typeof setInterval>|null>(null);const startTimeRef=useRef(0)
  const applyDoc=(value:string)=>{if(targetRef.current==='readme')setReadme(value);else setAgents(value)}
  const flushNow=()=>{if(flushTimerRef.current){clearInterval(flushTimerRef.current);flushTimerRef.current=null}applyDoc(accRef.current)}
  const scheduleFlush=()=>{if(flushTimerRef.current)return;flushTimerRef.current=setInterval(()=>applyDoc(accRef.current),100)}
  const cleanupOptimize=()=>{if(flushTimerRef.current){clearInterval(flushTimerRef.current);flushTimerRef.current=null}if(elapsedTimerRef.current){clearInterval(elapsedTimerRef.current);elapsedTimerRef.current=null}optimizingRef.current=false;setOptimizing(false);setOptimizeProgress(null)}
  const generate=async()=>{try{const result=await window.crazyParrot.parrot.generate(draft);setReadme(result.readme);setAgents(result.agents);setTab('readme')}catch(e){showError(e,setNotice)}}
  const save=async()=>{setBusy(true);try{onChange(await window.crazyParrot.parrot.save(project.id,readme,agents));setNotice(tr('Parrot 草稿已保存','Parrot draft saved'))}catch(e){showError(e,setNotice)}finally{setBusy(false)}}
  const approve=async()=>{setBusy(true);try{const next=await window.crazyParrot.parrot.save(project.id,readme,agents);onChange(next);const approved=await window.crazyParrot.parrot.approve(project.id);onChange(approved);onApproved()}catch(e){showError(e,setNotice)}finally{setBusy(false)}}
  const currentIssues=liveCheck?.issues??status.issues
  const currentValid=liveCheck?.valid??status.valid
  useEffect(()=>window.crazyParrot.parrot.onParrotOptimize(event=>{
    if(event.projectId!==project.id||event.runId!==activeRunRef.current)return
    if(event.type==='text'){accRef.current+=event.text;setOptimizeProgress(p=>p?{...p,chars:accRef.current.length}:p);scheduleFlush()}
    else if(event.type==='done'){flushNow();setOptimizeReport({issues:event.issues,truncated:event.truncated});activeRunRef.current=null;cleanupOptimize();setNotice(tr('AI 优化完成，请检查后保存','AI optimization done — review and save'))}
    else{flushNow();applyDoc(beforeRef.current);activeRunRef.current=null;cleanupOptimize();showError(new Error(event.error),setNotice)}
  }),[project.id,setNotice])
  // 实时完整性检查：编辑器内容变化（含 AI 流式输出）300ms 防抖后刷新“缺少章节”与“通过/待补充”
  useEffect(()=>{
    const timer=setTimeout(()=>{void window.crazyParrot.parrot.validate(readme,agents).then(setLiveCheck).catch(()=>{})},300)
    return ()=>clearTimeout(timer)
  },[readme,agents])
  // 体检评分：输入稳定 300ms 后计算；AI 优化流式期间跳过，流结束算最终一次
  useEffect(()=>{
    if(optimizing)return
    const timer=setTimeout(()=>{void window.crazyParrot.parrot.audit(readme,agents).then(setAudit).catch(()=>{})},300)
    return ()=>clearTimeout(timer)
  },[readme,agents,optimizing])
  const optimize=async()=>{
    if(optimizingRef.current)return;optimizingRef.current=true
    const target:ParrotOptimizeTarget=tab==='agents'?'agents':'readme';const text=target==='readme'?readme:agents
    targetRef.current=target;beforeRef.current=text;accRef.current='';setOptimizeReport(null);setOptimizing(true)
    startTimeRef.current=Date.now();setOptimizeProgress({chars:0,elapsedSec:0})
    elapsedTimerRef.current=setInterval(()=>setOptimizeProgress(p=>p?{...p,elapsedSec:Math.floor((Date.now()-startTimeRef.current)/1000)}:p),1000)
    try{const trimmed=instruction.trim();const {runId}=await window.crazyParrot.parrot.aiOptimize({projectId:project.id,target,text,...(trimmed?{instruction:trimmed}:{}),...(optimizeProviderId?{providerId:optimizeProviderId}:{})});activeRunRef.current=runId}
    catch(e){activeRunRef.current=null;cleanupOptimize();showError(e,setNotice)}
  }
  const discard=()=>{activeRunRef.current=null;flushNow();applyDoc(beforeRef.current);setOptimizeReport(null);cleanupOptimize();setNotice(tr('已恢复优化前内容','Reverted to the content before optimization'))}
  return <section className="page parrot-page"><div className="page-heading"><div><div className="eyebrow">{project.name}</div><h1>{tr('项目 Parrot','Project Parrot')}</h1></div><div className="stepper"><span className="done">1</span><i/><span className={readme?'done':''}>2</span><i/><span className={status.approved?'done':''}>3</span></div></div>
    <div className="parrot-layout"><div className="editor-card"><div className="tabs"><button className={tab==='wizard'?'active':''} onClick={()=>setTab('wizard')}>{tr('向导','Setup')}</button><button className={tab==='readme'?'active':''} onClick={()=>setTab('readme')}>README.md</button><button className={tab==='agents'?'active':''} onClick={()=>setTab('agents')}>AGENTS.md</button></div>
      {tab==='wizard'?<div className="wizard"><Field label={tr('项目名称','Project name')} value={draft.name} onChange={v=>setDraft({...draft,name:v})}/><Field label={tr('项目目标','Goals')} value={draft.goals} onChange={v=>setDraft({...draft,goals:v})} area/><div className="form-row"><Field label={tr('目标用户','Audience')} value={draft.audience} onChange={v=>setDraft({...draft,audience:v})}/><Field label={tr('技术栈','Stack')} value={draft.stack} onChange={v=>setDraft({...draft,stack:v})}/></div><Field label={tr('核心功能（每行一项）','Core features (one per line)')} value={draft.features} onChange={v=>setDraft({...draft,features:v})} area/><Field label={tr('明确不做','Non-goals')} value={draft.nonGoals} onChange={v=>setDraft({...draft,nonGoals:v})} area/><Field label={tr('启动、构建与测试命令','Run, build, and test commands')} value={draft.commands} onChange={v=>setDraft({...draft,commands:v})} area/><Field label={tr('额外开发约束','Additional constraints')} value={draft.constraints} onChange={v=>setDraft({...draft,constraints:v})} area/><button className="primary" disabled={optimizing} onClick={()=>void generate()}>{tr('生成草稿','Generate draft')}</button></div>:<>
        <div className="optimize-bar"><input value={instruction} onChange={e=>setInstruction(e.target.value)} placeholder={tr('可选指令，如"补充部署章节"','Optional instruction, e.g. "add a deployment section"')} disabled={optimizing} aria-label={tr('优化指令','Optimization instruction')}/>{verified.length>1&&<select value={optimizeProviderId} onChange={e=>setOptimizeProviderId(e.target.value)} aria-label={tr('优化模型','Model')}>{verified.map(p=><option key={p.id} value={p.id}>{p.name} · {p.model}</option>)}</select>}<button className="primary" disabled={!optimizeProviderId||optimizing||busy} onClick={()=>void optimize()}>{optimizing?tr('优化中…','Optimizing…'):'✨ '+tr('AI 优化','AI optimize')}</button>{(optimizing||optimizeReport)&&<button onClick={discard}>{tr('丢弃','Discard')}</button>}</div>
        {optimizing&&optimizeProgress&&<div className="optimize-progress" role="status" aria-live="polite"><div className="optimize-progress-track"><i/></div><span>{tr('已生成','Generated')} {optimizeProgress.chars} {tr('字符','chars')} · {optimizeProgress.elapsedSec}s</span></div>}
        {optimizeReport&&<div className="optimize-report">{optimizeReport.truncated&&<div className="optimize-truncated">⚠ {tr('输出可能被截断，请检查完整性','Output may be truncated — check completeness')}</div>}{optimizeReport.issues.map((issue,i)=><div className={`issues-row ${issue.severity}`} key={i}><span>{issue.severity==='error'?'×':'!'}</span>{issue.message}</div>)}<div className="optimize-hint">{tr('AI 结果已填入编辑器，请检查后手动保存','AI result is in the editor — review it, then save manually')}</div></div>}
        <MonacoEditor value={tab==='readme'?readme:agents} language="markdown" onChange={v=>tab==='readme'?setReadme(v):setAgents(v)} className="code-editor" readOnly={optimizing} ariaLabel={tab==='readme'?'README.md':'AGENTS.md'}/></>}</div>
      <aside className="audit-card"><div className="audit-head"><span>{tr('检查','Review')}</span><b className={currentValid?'good':'bad'}>{currentValid?tr('通过','Ready'):tr('待补充','Incomplete')}</b>{audit&&<b className={`audit-score ${audit.level}`} title={tr('Parrot 健康度','Parrot health')}>{audit.score}</b>}</div><div className="parrot-files"><div className={readme?'ok':''}><span>{readme?'✓':'!'}</span><div>README.md</div></div><div className={agents?'ok':''}><span>{agents?'✓':'!'}</span><div>AGENTS.md</div></div></div>{audit&&<div className="audit-items">{audit.items.map(item=><div className="audit-item" key={item.key}><div className="audit-item-top"><span>{auditItemLabel(item.key)}</span><b>{item.score}/{item.max}</b></div><div className="audit-bar"><i style={{width:`${item.max?Math.round(item.score/item.max*100):0}%`}}/></div></div>)}</div>}{audit&&audit.issues.length>0&&<div className="audit-issues">{audit.issues.map((issue,i)=><div className="audit-issue" key={i}>{issue.message}<small>{issue.suggestion}</small></div>)}</div>}<div className="issues">{currentIssues.length?currentIssues.map((i,n)=><div key={n} className={i.severity}><span>{i.severity==='error'?'×':'!'}</span>{i.message}</div>):<div className="success-box">✓ {tr('检查通过','Ready')}</div>}</div><div className="audit-actions"><button disabled={busy||optimizing} onClick={()=>void save()}>{tr('保存','Save')}</button><button className="primary" disabled={busy||optimizing} onClick={()=>void approve()}>{tr('确认','Confirm')}</button></div></aside></div>
  </section>
}

function Workspace({project,parrot,providers,tasks,events,refreshTasks,setNotice,editParrot}:{project:ProjectRecord;parrot:ParrotStatus;providers:ProviderProfile[];tasks:TaskRecord[];events:Record<string,AgentEvent[]>;refreshTasks:()=>Promise<void>|void;setNotice:(s:string)=>void;editParrot():void}){
  const verified=providers.filter(p=>p.verifiedAt);const [providerId,setProviderId]=useState(verified[0]?.id??'');const [prompt,setPrompt]=useState('');const [mode,setMode]=useState<TaskMode>('edit');const [agentTab,setAgentTab]=useState<'chat'|'task'>('chat');const [selectedFile,setSelectedFile]=useState<ProjectFileContent|null>(null);const [selectedId,setSelectedId]=useState<string|null>(tasks[0]?.id??null);const [compacting,setCompacting]=useState(false);const [paneWidths,setPaneWidths]=useState({explorer:230,agent:430});const dragRef=useRef<{kind:'explorer'|'agent';startX:number;startWidth:number}|null>(null);const selected=selectedId?tasks.find(t=>t.id===selectedId):undefined
  const conversation=useMemo(()=>taskConversation(tasks,selected?.id),[tasks,selected?.id]);const visibleEvents=conversation.flatMap(item=>conversationEvents(events[item.id]??[]));const scrollRef=useRef<HTMLDivElement>(null);const streamLength=visibleEvents.at(-1)?.message.length??0;const shouldStickToBottomRef=useRef(true);const [draggedTaskId,setDraggedTaskId]=useState<string|null>(null)
  useEffect(()=>{setSelectedId(tasks[0]?.id??null)},[project.id])
  useEffect(()=>{const move=(event:PointerEvent)=>{const drag=dragRef.current;if(!drag)return;const delta=event.clientX-drag.startX;if(drag.kind==='explorer')setPaneWidths(widths=>({...widths,explorer:Math.min(420,Math.max(170,drag.startWidth+delta))}));else setPaneWidths(widths=>({...widths,agent:Math.min(680,Math.max(300,drag.startWidth-delta))}))};const stop=()=>{dragRef.current=null;document.body.classList.remove('is-resizing')};window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);return()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop)}},[])
  const startResize=(kind:'explorer'|'agent',event:React.PointerEvent)=>{event.preventDefault();dragRef.current={kind,startX:event.clientX,startWidth:paneWidths[kind]};document.body.classList.add('is-resizing')}
  useEffect(()=>{const node=scrollRef.current;if(!node)return;node.scrollTop=node.scrollHeight;shouldStickToBottomRef.current=true},[selected?.id])
  useEffect(()=>{const node=scrollRef.current;if(!node||!shouldStickToBottomRef.current)return;node.scrollTop=node.scrollHeight},[selected?.status,selected?.evidence,visibleEvents.length,streamLength])
  const submit=async()=>{if(!prompt.trim()||!providerId)return;try{const task=await window.crazyParrot.tasks.create(project.id,prompt.trim(),providerId,mode,selected?.id);setPrompt('');setSelectedId(task.id);setAgentTab('chat');shouldStickToBottomRef.current=true;await refreshTasks()}catch(e){showError(e,setNotice)}}
  const reorderTasks=async(sourceId:string,targetId:string)=>{if(sourceId===targetId)return;const queued=tasks.filter(task=>task.status==='queued');const sourceIndex=queued.findIndex(task=>task.id===sourceId);const targetIndex=queued.findIndex(task=>task.id===targetId);if(sourceIndex<0||targetIndex<0)return;const next=[...queued];const [moved]=next.splice(sourceIndex,1);if(!moved)return;next.splice(targetIndex,0,moved);try{await window.crazyParrot.tasks.reorder(project.id,next.map(task=>task.id));await refreshTasks()}catch(e){showError(e,setNotice)}finally{setDraggedTaskId(null)}}
  const approve=async()=>{if(selected)try{await window.crazyParrot.tasks.approve(selected.id);await refreshTasks()}catch(e){showError(e,setNotice)}}
  const compact=async()=>{if(!selected||compacting)return;setCompacting(true);try{await window.crazyParrot.tasks.compact(selected.id);await refreshTasks();setNotice(tr('上下文已压缩','Context compacted'))}catch(e){showError(e,setNotice)}finally{setCompacting(false)}}
  const revert=async()=>{if(selected&&confirm(tr('恢复到任务开始前的状态？本任务创建的文件将被删除。','Restore the state from before this task? Files created by this task will be removed.'))){await window.crazyParrot.tasks.revert(selected.id);await refreshTasks()}}
  const gridStyle={'--explorer-width':`${paneWidths.explorer}px`,'--agent-width':`${paneWidths.agent}px`} as React.CSSProperties
  return <section className="workspace"><div className="workspace-top"><div><span className="project-badge">{project.name.slice(0,2).toUpperCase()}</span><div className="workspace-project-name"><h2>{project.name}</h2><button onClick={()=>void window.crazyParrot.app.openPath(project.path)} title={project.path}>{project.path}</button></div></div><div><button className="parrot-status-button" onClick={editParrot}>{tr('Parrot','Parrot')} <span className={parrot.valid?'verified':'parrot-invalid'}>{parrot.valid?'✓':'!'}</span></button></div></div>
    <div className="workspace-grid editor-layout" style={gridStyle}><aside className="explorer-pane"><div className="pane-title">{tr('文件','Files')}</div><FileExplorer project={project} selectedPath={selectedFile?.path} onSelect={setSelectedFile} setNotice={setNotice}/></aside><div className="split-handle" role="separator" aria-label={tr('调整文件栏宽度','Resize file pane')} onPointerDown={event=>startResize('explorer',event)} />
      <section className="editor-pane">{selectedFile?<FilePreview file={selectedFile} onBack={()=>setSelectedFile(null)}/>:<div className="editor-empty"><span>{'{ }'}</span><h3>{tr('选择文件','Select a file')}</h3></div>}</section><div className="split-handle" role="separator" aria-label={tr('调整对话栏宽度','Resize agent pane')} onPointerDown={event=>startResize('agent',event)} />
      <aside className="agent-pane"><div className="agent-toolbar"><div className="task-history-control"><select aria-label={tr('任务历史','Task history')} value={selected?.id??''} onChange={e=>setSelectedId(e.target.value||null)}><option value="">{tr('新对话','New conversation')}</option>{tasks.map(t=><option key={t.id} value={t.id}>{t.parentTaskId?'↳ ':''}{statusText(t.status)} · {t.prompt}</option>)}</select>{tasks.some(task=>task.status==='queued')&&<span className="queue-count">{tasks.filter(task=>task.status==='queued').length} {tr('待发送','queued')}</span>}</div>{selected&&<button className={`compact-context ${selected.contextSummary?'done':''}`} disabled={compacting||Boolean(selected.contextSummary)||['planning','running','awaiting_approval','queued'].includes(selected.status)} onClick={()=>void compact()} title={tr('压缩此前对话，减少后续上下文占用','Summarize prior turns to reduce context usage')}>{selected.contextSummary?tr('已压缩','Compacted'):tr('压缩','Compact')}</button>}<div className="agent-tabs"><button className={agentTab==='chat'?'active':''} onClick={()=>setAgentTab('chat')}>{tr('对话','Chat')}</button><button className={agentTab==='task'?'active':''} onClick={()=>setAgentTab('task')}>{tr('任务','Task')}</button></div></div>{tasks.some(task=>task.status==='queued')&&<div className="pending-queue" aria-label={tr('待发送任务','Queued tasks')}><div className="pending-queue-title"><span>{tr('待发送','Queued')}</span><small>{tr('拖拽调整顺序','Drag to reorder')}</small></div>{tasks.filter(task=>task.status==='queued').map(task=><button key={task.id} className={`queued-task ${draggedTaskId===task.id?'dragging':''}`} draggable onDragStart={()=>setDraggedTaskId(task.id)} onDragEnd={()=>setDraggedTaskId(null)} onDragOver={event=>event.preventDefault()} onDrop={()=>draggedTaskId&&void reorderTasks(draggedTaskId,task.id)} onClick={()=>setSelectedId(task.id)}><span className="queue-grip" aria-hidden="true">⋮⋮</span><span className="status queued"/><span className="queued-task-prompt">{task.prompt}</span></button>)}</div>}{agentTab==='chat'?<div className="conversation"><div className="conversation-scroll" ref={scrollRef} onScroll={event=>{const node=event.currentTarget;shouldStickToBottomRef.current=node.scrollHeight-node.scrollTop-node.clientHeight<48}}>{selected?conversation.map(item=><ConversationTurn key={item.id} task={item} events={conversationEvents(events[item.id]??[])} current={item.id===selected.id} approve={approve} revert={revert}/>):<div className="empty-conversation"><h2>{tr('新对话','New conversation')}</h2></div>}</div><div className="composer">{!verified.length&&<div className="composer-warning">{tr('请先连接模型','Connect a model first')}</div>}<div className="mode-switch" role="group" aria-label={tr('任务模式','Task mode')}>{(['ask','plan','edit'] as TaskMode[]).map(value=><button key={value} className={mode===value?'active':''} onClick={()=>setMode(value)} title={modeDescription(value)} aria-pressed={mode===value}><b>{modeLabel(value)}</b><span>{modeDescription(value)}</span></button>)}</div><textarea placeholder={selected?tr('继续对话…','Continue…'):modePlaceholder(mode)} value={prompt} onChange={e=>setPrompt(e.target.value)} onKeyDown={e=>{if(shouldSubmitPrompt(e.key,e.shiftKey,e.nativeEvent.isComposing)){e.preventDefault();void submit()}}}/><div className="composer-toolbar"><select aria-label={tr('模型','Model')} value={providerId} onChange={e=>setProviderId(e.target.value)}><option value="">{tr('选择模型','Select model')}</option>{verified.map(p=><option key={p.id} value={p.id}>{p.name} · {p.model}</option>)}</select><button className="send" aria-label={tr('发送','Send')} disabled={!verified.length||!prompt.trim()} onClick={()=>void submit()}><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 15V5m0 0L6.5 8.5M10 5l3.5 3.5"/></svg></button></div></div></div>:<TaskInspector selected={selected} editParrot={editParrot} approve={approve} revert={revert} setNotice={setNotice}/>}</aside></div>
  </section>
}

function ConversationTurn({task,events,current,approve,revert}:{task:TaskRecord;events:AgentEvent[];current:boolean;approve:()=>Promise<void>;revert:()=>Promise<void>}){
  const showPlan=task.mode==='edit'||task.mode==='plan'
  const terminal=['completed','failed','cancelled','reverted'].includes(task.status)
  return <div className={`conversation-turn ${current?'current':''}`}><div className="user-message"><small>{modeLabel(task.mode)}</small>{task.prompt}</div>{showPlan&&<PlanCard task={task}/>}<div className="event-stream">{events.map((event,index)=><EventRow event={event} key={index} onApprove={current&&task.status==='awaiting_approval'?approve:undefined}/>)}</div>{terminal&&<ReceiptCard taskId={task.id} onRevert={current&&task.mode==='edit'?revert:undefined}/>} {task.mode==='edit'&&task.evidence&&<EvidenceCard task={task} onRevert={undefined}/>} {task.error&&<div className="error-card">{task.error}</div>}</div>
}

function PlanCard({task}:{task:TaskRecord}){const planOnly=task.mode==='plan';const required=!planOnly&&task.mode==='edit'&&task.riskLevel!=='low';return <div className={`plan-card change-intent ${planOnly?'plan-only':''}`}><div><span>{planOnly?tr('实施方案','Implementation plan'):tr('变更意图（建议）','Change intent (advisory)')}</span><b className={planOnly?'plan-readonly':`risk ${task.riskLevel}`}>{planOnly?tr('只读','Read-only'):task.riskLevel}</b></div><p>{task.plan.summary}</p><small className="intent-note">{planOnly?tr('Plan 只会检查和规划：不改文件、不运行命令、不创建快照。切换到 Edit 并重新发送后才会实际执行。','Plan only inspects and proposes: no file edits, commands, or snapshots. Switch to Edit and send a new task to make changes.'):tr('这是基于当前任务的初步范围；Agent 探索后可能需要追加文件或命令批准。','This is an initial scope estimate. The agent may request more approvals after it explores the project.')}</small><div className="intent-grid"><section><b>{planOnly?tr('先检查','Inspect first'):tr('预计文件','Predicted files')}</b>{task.plan.affectedPaths.length?task.plan.affectedPaths.map(path=><code key={path}>{path}</code>):<small>{tr('尚未预测具体文件','No specific files predicted yet')}</small>}</section><section><b>{tr('验收检查','Acceptance checks')}</b>{task.plan.acceptanceChecks.length?task.plan.acceptanceChecks.map(check=><small key={check}>✓ {check}</small>):<small>{tr('由项目 Parrot 决定','Defined by project Parrot')}</small>}</section><section><b>{planOnly?tr('执行边界','Execution boundary'):tr('需要批准','Required approvals')}</b><small>{planOnly?tr('只读工具；结果是可审阅方案，不是已完成的修改。','Read-only tools; the result is a reviewable proposal, not completed work.'):required?tr('此风险等级需要任务批准；范围、命令或预算扩大时会额外请求。','This risk needs task approval; scope, command, or budget changes can require more.'):tr('初始计划无需任务批准；后续敏感命令或写入仍会请求批准。','No initial task approval; later sensitive commands or writes can still request approval.')}</small></section></div>{task.plan.commands.map(c=><pre className="planned-command" key={c.command}>{c.command}<small>{c.reason}</small></pre>)}{task.status==='awaiting_approval'&&<small>{tr('等待确认','Waiting for approval')}</small>}</div>}
function EventRow({event,onApprove}:{event:AgentEvent;onApprove:(()=>Promise<void>)|undefined}){
  if(event.type==='terminal')return <TerminalView event={event}/>
  if(event.type==='evidence')return null
  if(event.type==='text')return <div className="assistant-message"><span>CP</span><div className="markdown-body"><ReactMarkdown>{event.message}</ReactMarkdown></div></div>
  if(event.type==='reasoning')return <details className="reasoning-card" open><summary>{tr('思考','Reasoning')}</summary><div className="markdown-body"><ReactMarkdown>{event.message}</ReactMarkdown></div></details>
  if(event.type==='tool')return <ToolEvent event={event}/>
  if(event.type==='approval')return <ApprovalEvent event={event} onApprove={onApprove}/>
  return <div className={`event-row event-${event.type}`}><span>{event.type==='error'?'×':'●'}</span><div>{localizeServerMessage(event.message)}</div></div>
}

function ToolEvent({event}:{event:AgentEvent}){
  const payload=asPayload(event.payload);const name=event.message.split(':',1)[0]??'tool';const command=stringValue(payload.command);const path=stringValue(payload.path);const query=stringValue(payload.query);const detail=command||path||query
  const labels:Record<string,string>={read_file:tr('读取文件','Read file'),list_files:tr('查看目录','List files'),search_files:tr('搜索','Search'),write_file:tr('写入文件','Write file'),replace_in_file:tr('修改文件','Edit file'),run_command:tr('运行命令','Run command')}
  return <div className="tool-event"><div className="event-icon">◇</div><div><div className="event-title">{labels[name]??name}</div>{detail&&(command?<pre>{command}</pre>:<code>{detail}</code>)}{query&&path&&<small>{path}</small>}</div></div>
}

function ApprovalEvent({event,onApprove}:{event:AgentEvent;onApprove:(()=>Promise<void>)|undefined}){
  const payload=asPayload(event.payload);const direct=stringValue(payload.command);const planned=Array.isArray(payload.commands)?payload.commands.map(item=>asPayload(item)).map(item=>({command:stringValue(item.command),reason:stringValue(item.reason)})).filter(item=>item.command):[];const commands=direct?[{command:direct,reason:stringValue(payload.reason)}]:planned;const paths=Array.isArray(payload.paths)?payload.paths.filter((item):item is string=>typeof item==='string'):[];const kind=stringValue(payload.kind);const rawRisk=(stringValue(payload.risk)||stringValue(payload.riskLevel)).toLowerCase();const risk=['low','medium','high'].includes(rawRisk)?rawRisk:'medium';const commandApproval=commands.length>0;const budgetApproval=kind==='budget';const fileApproval=kind==='file-change'||kind==='change-scope'
  const title=commandApproval?tr('命令执行需要你的批准','Command execution needs your approval'):budgetApproval?tr('任务预算已达到上限','Task budget limit reached'):fileApproval?tr('文件变更范围需要确认','File change scope needs approval'):tr('任务执行需要你的批准','Task execution needs your approval')
  const summary=commandApproval?tr(`Agent 请求运行 ${commands.length} 条命令。请核对命令和理由后再继续。`,`The agent wants to run ${commands.length} command${commands.length===1?'':'s'}. Review the details before continuing.`):budgetApproval?tr('继续后将忽略此任务的预算上限；请确认额外消耗仍在可接受范围内。','Continuing will ignore this task\'s budget cap. Confirm that the additional usage is acceptable.'):fileApproval?tr('Agent 即将进行较大范围或敏感配置变更。请先核对受影响路径。','The agent is about to make a broad or sensitive configuration change. Review the affected paths first.'):localizeServerMessage(event.message)
  return <section className={`approval-event approval-${risk}`} aria-label={tr('执行确认','Execution approval')}><div className="approval-top"><div className="approval-icon" aria-hidden="true">!</div><div className="approval-title"><span>{commandApproval?tr('执行确认','Execution approval'):tr('任务确认','Task approval')}</span><h3>{title}</h3></div><b className={`approval-risk ${risk}`}>{risk}</b></div><p className="approval-summary">{summary}</p>{commandApproval&&<div className="approval-commands">{commands.map((item,index)=><div className="approval-command" key={`${item.command}-${index}`}><div className="approval-command-head"><span>{tr('待执行命令','Command to run')} {commands.length>1?`${index+1}/${commands.length}`:''}</span></div><pre>{item.command}</pre>{item.reason&&<div className="approval-reason"><span aria-hidden="true">↳</span>{item.reason}</div>}</div>)}</div>}{fileApproval&&paths.length>0&&<div className="approval-paths">{paths.map(path=><code key={path}>{path}</code>)}</div>}<div className="approval-actions"><small>{tr('批准后，Agent 将从当前步骤继续执行。','After approval, the agent will continue from the current step.')}</small>{onApprove&&<button className="primary" onClick={()=>void onApprove()}>{tr('批准并继续','Approve & continue')} <span aria-hidden="true">→</span></button>}</div></section>
}

function asPayload(value:unknown):Record<string,unknown>{return value!==null&&typeof value==='object'&&!Array.isArray(value)?value as Record<string,unknown>:{}}
function stringValue(value:unknown):string{return typeof value==='string'?value:''}
function ReceiptCard({taskId,onRevert}:{taskId:string;onRevert:(()=>void)|undefined}){
  const [detail,setDetail]=useState<ChangeReceiptDetail|null|undefined>(undefined);const [drift,setDrift]=useState<ReceiptDrift|null>(null);const [busy,setBusy]=useState(false)
  const load=useCallback(async()=>{try{setDetail(await window.crazyParrot.receipts.get(taskId))}catch{setDetail(null)}},[taskId])
  useEffect(()=>{void load()},[load])
  const checkDrift=async()=>{setBusy(true);try{setDrift(await window.crazyParrot.receipts.drift(taskId))}finally{setBusy(false)}}
  const exportReceipt=async(format:'markdown'|'json')=>{setBusy(true);try{await window.crazyParrot.receipts.export(taskId,format)}finally{setBusy(false)}}
  if(detail===undefined)return <div className="receipt-card receipt-loading">{tr('正在生成变更凭证…','Creating Change Receipt…')}</div>
  if(!detail)return <div className="receipt-card receipt-unavailable"><b>{tr('变更凭证不可用','Change Receipt unavailable')}</b><small>{tr('这是旧任务；仅新任务会生成可验证凭证。','This is a legacy task. Only new tasks have verifiable receipts.')}</small></div>
  const receipt=detail.receipt;const driftLabel=drift?.state==='in-sync'?tr('当前工作区匹配','Workspace matches'):drift?.state==='drifted'?tr('检测到后续变更','Workspace drift detected'):drift?.state==='unavailable'?tr('无法检查工作区','Workspace unavailable'):''
  return <section className="receipt-card"><header><div><span>✓</span><div><small>{tr('变更凭证','Change Receipt')}</small><h3>{receipt.status==='reverted'?tr('已回退','Reverted'):tr('变更可证明、可回退','Proven & reversible')}</h3></div></div><code title={receipt.receiptHash}>{receipt.receiptHash.slice(0,12)}…</code></header><div className="receipt-summary"><div><b>{receipt.files.length}</b><small>{tr('文件','Files')}</small></div><div><b>{receipt.approvals.length}</b><small>{tr('已批准','Approved')}</small></div><div><b>{receipt.tests.filter(test=>test.passed).length}/{receipt.tests.length}</b><small>{tr('测试','Tests')}</small></div></div><div className="receipt-sections"><section><b>{tr('目标 / 模型','Goal / model')}</b><p>{receipt.goal}<br/><small>{receipt.provider?`${receipt.provider.name} · ${receipt.provider.model}`:tr('模型信息不可用','Provider unavailable')}{receipt.usage?` · ${(receipt.usage.inputTokens+receipt.usage.outputTokens).toLocaleString()} tokens · $${receipt.usage.estimatedCostUsd.toFixed(4)}`:''}</small></p></section><section><b>{tr('变更内容','What changed')}</b><p>{receipt.files.length?receipt.files.map(file=>file.path).join(' · '):tr('未记录文件变更','No file changes recorded')}</p></section><section><b>{tr('为何允许','Why allowed')}</b><p>{receipt.parrot.approved?tr('已依据已确认的 Parrot 执行。','Executed under an approved Parrot.'):tr('未记录 Parrot 确认。','No Parrot approval recorded.')} {receipt.approvals.length?tr(`${receipt.approvals.length} 次显式批准已记录。`,`${receipt.approvals.length} explicit approval${receipt.approvals.length===1?'':'s'} recorded.`):tr('无需显式批准。','No explicit approval was required.')}</p></section><section><b>{tr('如何验证','How verified')}</b><p>{receipt.verification.summary}</p></section><section><b>{tr('如何撤销','How to undo')}</b><p>{detail.snapshotPresent?tr('可恢复此任务开始前的本地快照。','Restore the local snapshot from before this task.'):tr('此任务没有可用快照。','No snapshot is available for this task.')}</p></section></div>{drift&&<div className={`receipt-drift ${drift.state}`}><b>{driftLabel}</b><small>{drift.files.filter(file=>file.status!=='in-sync').map(file=>`${file.path}: ${file.status}`).join(' · ')||tr('所有已跟踪文件均与凭证一致。','All tracked files match the receipt.')}</small></div>}<footer><button onClick={()=>void checkDrift()} disabled={busy}>{tr('检查工作区','Check workspace')}</button><button onClick={()=>void exportReceipt('markdown')} disabled={busy}>{tr('导出 Markdown','Export Markdown')}</button><button onClick={()=>void exportReceipt('json')} disabled={busy}>{tr('导出 JSON','Export JSON')}</button>{onRevert&&detail.snapshotPresent&&receipt.status!=='reverted'&&<button onClick={onRevert}>{tr('回退','Revert')}</button>}</footer></section>
}
function EvidenceCard({task,onRevert}:{task:TaskRecord;onRevert:(()=>void)|undefined}){
  const e=task.evidence!
  const [diffPath,setDiffPath]=useState<string|null>(null);const [diffContent,setDiffContent]=useState<DiffContent|null>(null);const [diffError,setDiffError]=useState('');const [diffLoading,setDiffLoading]=useState(false)
  const [compliance,setCompliance]=useState<ComplianceResult|null>(null)
  useEffect(()=>{
    let alive=true
    window.crazyParrot.parrot.compliance(task.projectId,e.changedFiles.map(f=>f.path))
      .then(result=>{if(alive)setCompliance(result)})
      .catch(()=>{if(alive)setCompliance(null)}) // fail-open：合规拉取失败不阻塞卡片
    return ()=>{alive=false}
  },[task.id,task.projectId,e])
  const violatedPaths=useMemo(()=>new Set(compliance?.violations.map(v=>v.path)??[]),[compliance])
  const toggleDiff=async(path:string)=>{
    if(diffPath===path){setDiffPath(null);setDiffContent(null);setDiffError('');return}
    setDiffPath(path);setDiffContent(null);setDiffError('');setDiffLoading(true)
    try{setDiffContent(await window.crazyParrot.snapshots.diffContent(task.id,path))}catch(error){setDiffError(error instanceof Error?error.message:String(error))}finally{setDiffLoading(false)}
  }
  return <div className="evidence-card"><div className="evidence-title"><div><span>✓</span><h3>{task.status==='reverted'?tr('已回退','Reverted'):tr('执行结果','Results')}</h3></div>{onRevert&&<button onClick={onRevert}>{tr('回退','Revert')}</button>}</div><div className="evidence-stats"><div><b>{e.changedFiles.length}</b><span>{tr('文件变更','Files')}</span></div><div><b>{e.commands.length}</b><span>{tr('执行命令','Commands')}</span></div><div><b>{e.tests.filter(t=>t.passed).length}/{e.tests.length}</b><span>{tr('测试通过','Tests')}</span></div></div>{compliance&&compliance.violations.length>0&&<div className="compliance-banner">{compliance.violations.map((v,i)=><div key={i}><span>✗</span>{localizeServerMessage(v.message)}</div>)}<small>{tr(`对照 Parrot ${compliance.checkedHash.slice(0,8)}…`,`Against Parrot ${compliance.checkedHash.slice(0,8)}…`)}</small></div>}{e.changedFiles.map(f=><div className="file-change" key={f.path}><button className={`file-change-row ${violatedPaths.has(f.path)?'violation':''}`} onClick={()=>void toggleDiff(f.path)}><span className={f.type}>{f.type.charAt(0).toUpperCase()}</span>{f.path}<i className={diffPath===f.path?'open':''}>▶</i></button>{diffPath===f.path&&(diffLoading?<p className="muted">{tr('加载 diff…','Loading diff…')}</p>:diffError?<p className="warning-text">{diffError}</p>:diffContent?<MonacoDiff original={diffContent.oldText} modified={diffContent.newText} language={languageForFile(f.path??'')} className="diff-view"/>:null)}</div>)}{e.remainingRisks.map((r,i)=><p className="warning-text" key={i}>! {localizeServerMessage(r)}</p>)}</div>
}
function Info({label,value,tone}:{label:string;value:string;tone?:string}){return <div className="info"><span>{label}</span><b className={tone}>{value}</b></div>}

function TaskInspector({selected,editParrot,approve,revert,setNotice}:{selected:TaskRecord|undefined;editParrot:()=>void;approve:()=>Promise<void>;revert:()=>Promise<void>;setNotice:(value:string)=>void}){
  if(!selected)return <p className="muted">{tr('选择一个任务','Select a task')}</p>
  const usage=selected.usage;const totalTokens=usage?usage.inputTokens+usage.outputTokens:0
  const resume=async()=>{try{await window.crazyParrot.tasks.resume(selected.id)}catch(error){showError(error,setNotice)}}
  return <div className="task-inspector"><div className="inspector-head">{tr('任务详情','Task details')}</div><Info label={tr('模式','Mode')} value={modeLabel(selected.mode)}/><Info label={tr('状态','Status')} value={statusText(selected.status)}/><Info label={tr('风险','Risk')} value={selected.riskLevel.toUpperCase()} tone={selected.riskLevel}/><Info label={tr('快照','Snapshot')} value={selected.mode==='edit'?tr('已保存','Saved'):tr('不适用','Not applicable')}/>{usage&&<><Info label={tr('Token 用量','Token use')} value={`${totalTokens.toLocaleString()} / ${usage.tokenLimit.toLocaleString()}`}/><Info label={tr('估算费用','Estimated cost')} value={usage.costLimitUsd>0?`$${usage.estimatedCostUsd.toFixed(4)} / $${usage.costLimitUsd.toFixed(2)}`:`$${usage.estimatedCostUsd.toFixed(4)}`}/><Info label={tr('模型请求','Model requests')} value={String(usage.requests)}/></>}{selected.plan.parrotConflicts.length>0&&<div className="conflict-box"><b>{tr('Parrot 冲突','Parrot conflicts')}</b>{selected.plan.parrotConflicts.map((c,i)=><p key={i}>{c.rule}<small>{c.explanation}</small></p>)}<button onClick={editParrot}>{tr('编辑 Parrot','Edit Parrot')}</button></div>}<div className="inspector-section"><h4>{tr('验收条件','Acceptance checks')}</h4>{selected.plan.acceptanceChecks.length?selected.plan.acceptanceChecks.map((v,i)=><p key={i}>✓ {v}</p>):<p>{tr('由项目 Parrot 决定','Defined by the project Parrot')}</p>}</div>{selected.status==='awaiting_approval'&&!selected.plan.parrotConflicts.length&&<button className="primary full" onClick={()=>void approve()}>{tr('批准并继续','Approve & continue')}</button>}{selected.status==='interrupted'&&selected.executionState&&<><button className="primary full" onClick={()=>void resume()}>{tr('从检查点恢复','Resume from checkpoint')}</button><button className="danger full" onClick={()=>void window.crazyParrot.tasks.cancel(selected.id)}>{tr('放弃恢复','Discard recovery')}</button></>}{selected.status==='running'&&<button className="danger full" onClick={()=>void window.crazyParrot.tasks.cancel(selected.id)}>{tr('停止','Stop')}</button>}{selected.mode==='edit'&&selected.evidence&&<button className="full" onClick={()=>void revert()}>↶ {tr('回退','Revert')}</button>}</div>
}

function FileExplorer({project,selectedPath,onSelect,setNotice}:{project:ProjectRecord;selectedPath:string|undefined;onSelect:(file:ProjectFileContent)=>void;setNotice:(s:string)=>void}){
  const [directories,setDirectories]=useState<Record<string,ProjectFileEntry[]>>({});const [expanded,setExpanded]=useState<Set<string>>(new Set());const [loadingPaths,setLoadingPaths]=useState<Set<string>>(new Set());const [loadingFile,setLoadingFile]=useState(false)
  const loadDirectory=useCallback(async(path:string,expand=false,refresh=false)=>{setLoadingPaths(previous=>new Set(previous).add(path));try{const entries=await window.crazyParrot.projects.files(project.id,path,refresh);setDirectories(previous=>({...previous,[path]:entries}));if(expand)setExpanded(previous=>new Set(previous).add(path))}catch(e){showError(e,setNotice)}finally{setLoadingPaths(previous=>{const next=new Set(previous);next.delete(path);return next})}},[project.id,setNotice])
  useEffect(()=>{setDirectories({});setExpanded(new Set());void loadDirectory('')},[loadDirectory])
  const openFile=async(entry:ProjectFileEntry)=>{setLoadingFile(true);try{onSelect(await window.crazyParrot.projects.readFile(project.id,entry.path))}catch(e){showError(e,setNotice)}finally{setLoadingFile(false)}}
  const toggleDirectory=async(entry:ProjectFileEntry)=>{if(expanded.has(entry.path)){setExpanded(previous=>{const next=new Set(previous);next.delete(entry.path);return next})}else{if(!directories[entry.path])await loadDirectory(entry.path);setExpanded(previous=>new Set(previous).add(entry.path))}}
  const renderEntries=(entries:ProjectFileEntry[],depth:number):React.ReactNode=>entries.map(entry=><React.Fragment key={entry.path}><button className={`file-entry ${selectedPath===entry.path?'active':''}`} style={{paddingLeft:8+depth*14}} aria-expanded={entry.type==='directory'?expanded.has(entry.path):undefined} onClick={()=>entry.type==='directory'?void toggleDirectory(entry):void openFile(entry)}><span className={`tree-toggle ${entry.type==='directory'?'':'hidden'}`}>{entry.type==='directory'?(expanded.has(entry.path)?'⌄':'›'):''}</span><span className={`file-icon ${entry.type}`}>{entry.type==='directory'?'□':fileGlyph(entry.name)}</span><b>{entry.name}</b>{entry.size!==undefined&&<small>{formatBytes(entry.size)}</small>}</button>{entry.type==='directory'&&expanded.has(entry.path)&&(loadingPaths.has(entry.path)?<div className="tree-loading" style={{paddingLeft:22+depth*14}}>{tr('读取中…','Loading…')}</div>:(directories[entry.path]?.length??0)>0?renderEntries(directories[entry.path]??[],depth+1):<div className="tree-empty" style={{paddingLeft:22+(depth+1)*14}}>{tr('空目录','Empty folder')}</div>)}</React.Fragment>)
  const rootEntries=directories['']??[]
  return <div className="file-explorer"><div className="file-toolbar"><div className="tree-root-label"><span className="file-icon folder">□</span><b>{project.name}</b></div><button className="icon-button" aria-label={tr('刷新文件','Refresh files')} onClick={()=>void loadDirectory('',false,true)}>↻</button></div><div className="file-list">{renderEntries(rootEntries,0)}{!loadingPaths.has('')&&!rootEntries.length&&<p className="muted">{tr('空目录','Empty folder')}</p>}</div>{(loadingPaths.has('')||loadingFile)&&<div className="file-loading">{tr('正在读取…','Loading…')}</div>}</div>
}

function FilePreview({file,onBack}:{file:ProjectFileContent;onBack:()=>void}){return <div className="file-preview"><div className="file-preview-head"><button onClick={onBack}>←</button><div><b>{file.path.split('/').at(-1)}</b><small>{file.path}</small></div><span>{formatBytes(file.size)}</span></div>{file.binary?<div className="binary-file">{tr('无法预览二进制文件','Binary preview is unavailable')}</div>:<MonacoEditor value={file.content} language={languageForFile(file.path)} readOnly className="code-preview"/>}{file.truncated&&<div className="truncated-note">{tr('仅显示前 1 MB','Showing the first 1 MB')}</div>}</div>}

const modeLabel=(mode:TaskMode)=>({ask:'Ask',plan:'Plan',edit:'Edit'}[mode])
const modeDescription=(mode:TaskMode)=>language==='zh'?({ask:'只读问答',plan:'只读规划',edit:'修改与验证'}[mode]):({ask:'Read-only answers',plan:'Read-only planning',edit:'Change and verify'}[mode])
const modePlaceholder=(mode:TaskMode)=>language==='zh'?({ask:'询问项目或代码…',plan:'描述目标，制定实施方案…',edit:'描述要完成的开发任务…'}[mode]):({ask:'Ask about this project or its code…',plan:'Describe the goal to create an implementation plan…',edit:'Describe the development task…'}[mode])
const fileGlyph=(name:string)=>/\.(ts|tsx|js|jsx)$/.test(name)?'TS':/\.md$/i.test(name)?'M↓':/\.json$/i.test(name)?'{}':'·'
function localizeServerMessage(message:string):string {
  if(language==='zh')return message
  const known:Record<string,string>={'已创建任务安全快照':'Task snapshot created','模型正在分析项目和任务':'The model is analyzing the project and task','已保存快照':'Snapshot saved','正在分析':'Analyzing','任务执行完成':'Task completed','任务已停止':'Task stopped','已恢复到任务开始前状态':'Restored the pre-task state','Agent 未运行可识别的测试命令，请人工验证':'No recognized test command was run. Manual verification is required.'}
  return known[message]??message.replace(/^连接成功，发现 (\d+) 个模型$/,(_,count:string)=>`Connection successful. Found ${count} models.`).replace(/^缺少“(.+)”章节$/,(_,section:string)=>`Missing required section: ${section}`).replace(/^路径 (.+) 受项目 Parrot 保护，Agent 不得写入$/,(_,path:string)=>`Path ${path} is protected by the project Parrot. The agent must not write there.`).replace(/^(.+\.md) 属于 Parrot 文件，当前 Parrot 未确认$/,(_,file:string)=>`${file} is a Parrot file, and the current Parrot is not confirmed.`)
}

function ProvidersView({providers,refresh,setNotice,embedded=false}:{providers:ProviderProfile[];refresh:()=>Promise<void>;setNotice:(s:string)=>void;embedded?:boolean}){
  const [form,setForm]=useState<ProviderInput>(blankProvider);const [busy,setBusy]=useState(false);const [models,setModels]=useState<string[]>([]);const [headersText,setHeadersText]=useState('{}')
  const presets=providerPresets()
  const selectPreset=(presetId:string)=>{const p=presets.find(x=>x.id===presetId);if(p){setForm({...blankProvider,name:p.name,protocol:p.protocol,baseUrl:p.baseUrl,model:p.model});setHeadersText('{}')}}
  const edit=(p:ProviderProfile)=>{setForm({...p,apiKey:''});setHeadersText(JSON.stringify(p.customHeaders??{},null,2))}
  const materialize=():ProviderInput=>{const parsed=JSON.parse(headersText) as unknown;if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw new Error(tr('自定义请求头必须是 JSON 对象','Custom headers must be a JSON object'));return {...form,customHeaders:parsed as Record<string,string>}}
  const save=async()=>{setBusy(true);try{const input=materialize();const saved=await window.crazyParrot.providers.save(input);setForm({...input,id:saved.id,apiKey:''});await refresh();setNotice(tr('模型配置已保存，请测试连接','Model profile saved. Test the connection.'))}catch(e){showError(e,setNotice)}finally{setBusy(false)}}
  const test=async()=>{setBusy(true);try{const result=await window.crazyParrot.providers.test(materialize());setModels((result.models??[]).map(m=>m.id));await refresh();setNotice(localizeServerMessage(result.message))}catch(e){showError(e,setNotice)}finally{setBusy(false)}}
  const content=<div className="settings-grid"><div className="provider-list"><h3>{tr('模型','Models')}</h3>{providers.map(p=><button key={p.id} onClick={()=>edit(p)} className={form.id===p.id?'active':''}><span className="provider-logo">{p.name.slice(0,2).toUpperCase()}</span><div><b>{p.name}</b><small>{p.model} · {p.protocol==='anthropic-messages'?'Anthropic':'OpenAI'}</small></div><i className={p.verifiedAt?'connected':''}>{p.verifiedAt?tr('可用','Ready'):tr('未测试','Untested')}</i></button>)}{!providers.length&&<div className="empty-small">{tr('暂无模型','No models')}</div>}</div><div className="provider-form"><div className="preset-row"><span>{tr('模板','Presets')}</span>{presets.map(p=><button key={p.id} onClick={()=>selectPreset(p.id)}>{p.name}</button>)}</div><div className="form-row"><Field label={tr('名称','Name')} value={form.name} onChange={v=>setForm({...form,name:v})}/><label className="field"><span>{tr('协议','Protocol')}</span><select value={form.protocol} onChange={e=>setForm({...form,protocol:e.target.value as ProviderInput['protocol']})}><option value="openai-chat">OpenAI Chat Completions</option><option value="anthropic-messages">Anthropic Messages</option></select></label></div><Field label="Base URL" value={form.baseUrl} onChange={v=>setForm({...form,baseUrl:v})}/><div className="form-row"><Field label={tr('模型','Model')} value={form.model} onChange={v=>setForm({...form,model:v})}/><Field label={form.id?tr('API 密钥（留空不变）','API key (blank to keep)'):tr('API 密钥','API key')} value={form.apiKey??''} onChange={v=>setForm({...form,apiKey:v})} password/></div><div className="form-row"><label className="field"><span>{tr('思考','Thinking')}</span><select value={form.thinkingEnabled?'on':'off'} onChange={e=>setForm({...form,thinkingEnabled:e.target.value==='on'})}><option value="off">{tr('关闭','Off')}</option><option value="on">{tr('开启','On')}</option></select></label><label className="field"><span>{tr('推理强度','Reasoning effort')}</span><select value={form.reasoningEffort} onChange={e=>setForm({...form,reasoningEffort:e.target.value as 'high'|'max'})}><option value="high">High</option><option value="max">Max</option></select></label></div><details><summary>{tr('高级配置','Advanced')}</summary><div className="form-row"><Field label={tr('最大上下文','Max context')} value={String(form.maxContext)} onChange={v=>setForm({...form,maxContext:Number(v)||128000})}/><Field label={tr('任务预算','Task budget')} value={String(form.taskBudget)} onChange={v=>setForm({...form,taskBudget:Number(v)||16000})}/><Field label={tr('超时（毫秒）','Timeout (ms)')} value={String(form.timeoutMs)} onChange={v=>setForm({...form,timeoutMs:Number(v)||120000})}/></div><div className="form-row"><Field label={tr('输入单价 / 百万 Token（USD）','Input price / M tokens (USD)')} value={String(form.inputPricePerMillion)} onChange={v=>setForm({...form,inputPricePerMillion:Math.max(0,Number(v)||0)})}/><Field label={tr('输出单价 / 百万 Token（USD）','Output price / M tokens (USD)')} value={String(form.outputPricePerMillion)} onChange={v=>setForm({...form,outputPricePerMillion:Math.max(0,Number(v)||0)})}/></div><small className="provider-pricing-hint">{tr('仅用于本地费用估算；填 0 即不计价。','Used only for local cost estimates; use 0 to disable pricing.')}</small><Field label={tr('自定义请求头（JSON）','Custom headers (JSON)')} value={headersText} onChange={setHeadersText} area/></details>{models.length>0&&<div className="model-results"><b>{tr('可用模型','Available models')}</b>{models.slice(0,12).map(m=><button key={m} onClick={()=>setForm({...form,model:m})}>{m}</button>)}</div>}<div className="form-actions"><button disabled={busy} onClick={()=>void test()}>{tr('测试','Test')}</button><button className="primary" disabled={busy} onClick={()=>void save()}>{tr('保存','Save')}</button>{form.id&&<button className="danger-link" onClick={async()=>{await window.crazyParrot.providers.remove(form.id!);setForm(blankProvider);setHeadersText('{}');await refresh()}}>{tr('删除','Delete')}</button>}</div></div></div>
  return embedded?content:<section className="page settings-page"><div className="page-heading"><div><h1>{tr('模型','Models')}</h1></div></div>{content}</section>
}

function SnapshotsView({snapshots,projects,refresh,setNotice}:{snapshots:SnapshotSummary[];projects:ProjectRecord[];refresh:()=>Promise<void>;setNotice:(s:string)=>void}){
  const [storage,setStorage]=useState<SnapshotStorage>({blobBytes:0,manifestBytes:0,totalBytes:0})
  const refreshStorage=()=>window.crazyParrot.snapshots.storage().then(setStorage)
  useEffect(()=>{void refreshStorage()},[snapshots])
  const remove=async(taskId:string)=>{if(!confirm(tr('删除此快照？删除后无法回退该任务。','Delete this snapshot? This task can no longer be reverted.')))return;try{await window.crazyParrot.snapshots.remove(taskId);await refresh();await refreshStorage();setNotice(tr('快照已删除','Snapshot deleted'))}catch(error){showError(error,setNotice)}}
  return <section className="page snapshot-page"><div className="page-heading"><div><h1>{tr('快照','Snapshots')}</h1><p>{tr('查看并管理任务快照；保留和空间策略位于右上角设置。','Review task snapshots. Retention and storage limits are in Settings.')}</p></div><div className="storage"><b>{formatBytes(storage.totalBytes)}</b><span>{tr('去重后的实际占用','Deduplicated disk use')}</span></div></div><div className="snapshot-table"><div className="table-head"><span>{tr('项目 / 任务','Project / task')}</span><span>{tr('创建时间','Created')}</span><span>{tr('内容大小','Content')}</span><span>{tr('排除项','Excluded')}</span><span/></div>{snapshots.map(s=><div key={s.taskId}><span><b>{s.projectName??projects.find(p=>p.id===s.projectId)?.name}</b><small>{s.taskId.slice(0,8)}</small></span><span>{formatTime(s.createdAt)}</span><span>{formatBytes(s.sizeBytes)}</span><span>{s.excludedPaths.length}</span><span><button onClick={()=>void remove(s.taskId)}>{tr('删除','Delete')}</button></span></div>)}{!snapshots.length&&<div className="empty-table">{tr('暂无快照','No snapshots')}</div>}</div></section>
}

function ReceiptsView({project,setNotice}:{project:ProjectRecord|null;setNotice:(s:string)=>void}){
  const [items,setItems]=useState<ChangeReceiptSummary[]>([]);const [selected,setSelected]=useState<ChangeReceiptDetail|null>(null);const [status,setStatus]=useState<'all'|ChangeReceiptSummary['status']>('all');const [risk,setRisk]=useState<'all'|TaskRecord['riskLevel']>('all');const [date,setDate]=useState<'all'|'7d'|'30d'>('all');const [model,setModel]=useState('');const [tests,setTests]=useState<'all'|'passed'|'failed'|'not-run'>('all');const [revertedOnly,setRevertedOnly]=useState(false);const [drift,setDrift]=useState<ReceiptDrift|null>(null)
  const load=useCallback(async()=>{if(!project){setItems([]);setSelected(null);return}const next=await window.crazyParrot.receipts.list(project.id);setItems(next)},[project])
  useEffect(()=>{void load()},[load])
  const filtered=useMemo(()=>items.filter(item=>{const age=Date.now()-new Date(item.capturedAt).getTime();const testState=item.totalTests===0?'not-run':item.passedTests===item.totalTests?'passed':'failed';return (status==='all'||item.status===status)&&(!revertedOnly||item.status==='reverted')&&(risk==='all'||item.riskLevel===risk)&&(date==='all'||age<=(date==='7d'?7:30)*86_400_000)&&(tests==='all'||testState===tests)&&(!model.trim()||(item.providerModel??'').toLocaleLowerCase().includes(model.trim().toLocaleLowerCase()))}),[items,status,risk,date,model,tests,revertedOnly])
  const open=async(taskId:string)=>{try{const detail=await window.crazyParrot.receipts.get(taskId);setSelected(detail);setDrift(null)}catch(error){showError(error,setNotice)}}
  const checkDrift=async()=>{if(!selected)return;try{setDrift(await window.crazyParrot.receipts.drift(selected.receipt.taskId))}catch(error){showError(error,setNotice)}}
  const exportReceipt=async(format:'markdown'|'json')=>{if(!selected)return;try{const result=await window.crazyParrot.receipts.export(selected.receipt.taskId,format);if(result)setNotice(tr('变更凭证已导出','Change Receipt exported'))}catch(error){showError(error,setNotice)}}
  if(!project)return <section className="page receipts-page"><div className="page-heading"><div><h1>{tr('变更凭证','Change Receipts')}</h1><p>{tr('选择项目以查看本地 AI 变更凭证。','Select a project to review local AI Change Receipts.')}</p></div></div><div className="empty-conversation"><h2>{tr('选择项目','Select a project')}</h2></div></section>
  return <section className="page receipts-page"><div className="page-heading"><div><div className="eyebrow">{project.name}</div><h1>{tr('变更凭证','Change Receipts')}</h1><p>{tr('每个新任务的本地、可审阅执行记录：改了什么、为何允许、如何验证，以及如何撤销。','A local, reviewable record for each new task: what changed, why it was allowed, how it was verified, and how to undo it.')}</p></div></div><div className="receipt-filters"><select value={status} onChange={event=>setStatus(event.target.value as typeof status)} aria-label={tr('状态','Status')}><option value="all">{tr('所有状态','All statuses')}</option><option value="completed">{tr('已完成','Completed')}</option><option value="failed">{tr('失败','Failed')}</option><option value="cancelled">{tr('已停止','Cancelled')}</option><option value="reverted">{tr('已回退','Reverted')}</option></select><select value={risk} onChange={event=>setRisk(event.target.value as typeof risk)} aria-label={tr('风险','Risk')}><option value="all">{tr('所有风险','All risk')}</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select><select value={date} onChange={event=>setDate(event.target.value as typeof date)} aria-label={tr('日期','Date')}><option value="all">{tr('所有日期','Any date')}</option><option value="7d">{tr('最近 7 天','Last 7 days')}</option><option value="30d">{tr('最近 30 天','Last 30 days')}</option></select><select value={tests} onChange={event=>setTests(event.target.value as typeof tests)} aria-label={tr('测试','Tests')}><option value="all">{tr('所有测试结果','Any tests')}</option><option value="passed">{tr('测试通过','Tests passed')}</option><option value="failed">{tr('测试失败','Tests failed')}</option><option value="not-run">{tr('未运行测试','No tests')}</option></select><input value={model} onChange={event=>setModel(event.target.value)} placeholder={tr('筛选模型…','Filter model…')}/><button className={revertedOnly?'active':''} onClick={()=>setRevertedOnly(value=>!value)}>{tr('仅已回退','Reverted only')}</button></div><div className="receipts-layout"><div className="receipt-index">{filtered.map(item=><button key={item.taskId} className={selected?.receipt.taskId===item.taskId?'active':''} onClick={()=>void open(item.taskId)}><div><b>{item.goal}</b><small>{formatTime(item.capturedAt)} · {item.providerModel??tr('无模型','No model')}</small></div><span className={`receipt-status ${item.status}`}>{statusText(item.status)}</span><small>{item.changedFileCount} {tr('文件','files')} · {item.passedTests}/{item.totalTests} {tr('测试','tests')}</small></button>)}{!filtered.length&&<div className="empty-table">{items.length?tr('没有符合筛选条件的凭证','No receipts match these filters'):tr('暂无变更凭证。旧任务会显示为不可用；发送新任务后将在此生成凭证。','No Change Receipts yet. Legacy tasks are unavailable; new tasks create receipts here.')}</div>}</div><aside className="receipt-detail">{selected?<ReceiptDetail receipt={selected.receipt} snapshotPresent={selected.snapshotPresent} drift={drift} onDrift={checkDrift} onExport={exportReceipt}/>:<div className="empty-conversation"><h2>{tr('选择一份凭证','Select a receipt')}</h2></div>}</aside></div></section>
}

function ReceiptDetail({receipt,snapshotPresent,drift,onDrift,onExport}:{receipt:ChangeReceipt;snapshotPresent:boolean;drift:ReceiptDrift|null;onDrift:()=>void;onExport:(format:'markdown'|'json')=>void}){return <div className="receipt-detail-inner"><header><span>✓</span><div><small>{tr('变更凭证','Change Receipt')}</small><h2>{statusText(receipt.status)}</h2><code>{receipt.receiptHash}</code></div></header><section><h3>{tr('任务目标与模型','Goal & model')}</h3><p>{receipt.goal}</p><p>{receipt.provider?`${receipt.provider.name} · ${receipt.provider.model} · ${receipt.provider.protocol}`:tr('模型信息不可用','Provider unavailable')}</p>{receipt.usage&&<p>{receipt.usage.inputTokens.toLocaleString()} in · {receipt.usage.outputTokens.toLocaleString()} out · {receipt.usage.requests} {tr('次请求','requests')} · ${receipt.usage.estimatedCostUsd.toFixed(4)}</p>}</section><section><h3>{tr('变更内容','What changed')}</h3>{receipt.files.length?receipt.files.map(file=><p key={file.path}><code>{file.path}</code> · {file.type}</p>):<p>{tr('没有文件变更','No file changes')}</p>}</section><section><h3>{tr('为何允许','Why it was allowed')}</h3><p>{receipt.parrot.approved?tr('任务以已确认的 Parrot 为准执行。','The task ran under an approved Parrot.'):tr('未记录 Parrot 确认。','No Parrot approval was recorded.')}</p>{receipt.approvals.length?receipt.approvals.map((approval,index)=><p key={index}><b>{approval.kind}</b> · {approval.reason}<small>{formatTime(approval.approvedAt)}</small></p>):<p>{tr('没有显式批准。','No explicit approvals.')}</p>}</section><section><h3>{tr('如何验证','How it was verified')}</h3><p>{receipt.verification.summary}</p>{receipt.tests.map((test,index)=><p key={index}><b>{test.passed?'PASS':'FAIL'}</b> <code>{test.command}</code></p>)}</section><section><h3>{tr('如何撤销','How to undo')}</h3><p>{snapshotPresent?tr(`恢复本地快照 ${receipt.rollback.snapshotId?.slice(0,8)??''} 即可回到任务开始前。`,`Restore local snapshot ${receipt.rollback.snapshotId?.slice(0,8)??''} to return to the pre-task state.`):tr('快照已不可用；凭证仍可用于检查后续工作区漂移。','Snapshot is unavailable; the receipt can still check workspace drift.')}</p></section>{drift&&<section className={`receipt-drift ${drift.state}`}><h3>{tr('工作区对比','Workspace comparison')}</h3><p>{drift.state==='in-sync'?tr('当前工作区与凭证基线一致。','Current workspace matches the receipt baseline.'):drift.state==='drifted'?tr('检测到任务后变更。','Changes after the task were detected.'):tr('无法读取当前工作区。','Current workspace could not be read.')}</p>{drift.files.filter(file=>file.status!=='in-sync').map(file=><p key={file.path}><code>{file.path}</code> · {file.status}</p>)}</section>}<footer><button onClick={onDrift}>{tr('检查工作区','Check workspace')}</button><button onClick={()=>onExport('markdown')}>{tr('导出 Markdown','Export Markdown')}</button><button onClick={()=>onExport('json')}>{tr('导出 JSON','Export JSON')}</button></footer><small className="receipt-privacy">{receipt.privacyNotice}</small></div>}

function SnapshotPolicyView({snapshots,refresh,setNotice}:{snapshots:SnapshotSummary[];refresh:()=>Promise<void>;setNotice:(s:string)=>void}){
  const [storage,setStorage]=useState<SnapshotStorage>({blobBytes:0,manifestBytes:0,totalBytes:0});const [policy,setPolicy]=useState<SnapshotPolicy>({retentionDays:30,maxBytes:5*1024*1024*1024})
  const refreshStorage=()=>window.crazyParrot.snapshots.storage().then(setStorage)
  useEffect(()=>{window.crazyParrot.snapshots.policy().then(setPolicy);void refreshStorage()},[snapshots])
  const save=async()=>{try{setPolicy(await window.crazyParrot.snapshots.savePolicy(policy));await refresh();await refreshStorage();setNotice(tr('快照策略已保存','Snapshot policy saved'))}catch(error){showError(error,setNotice)}}
  return <section className="settings-panel snapshot-policy-panel"><div className="settings-panel-head"><div><span>{tr('快照策略','Snapshot policy')}</span><h2>{tr('保留与存储','Retention & storage')}</h2><p>{tr('上限按照去重后的实际磁盘占用计算。空间不足时，新的编辑任务不会启动。','Limits use deduplicated disk usage. New edit tasks will not start when storage is unavailable.')}</p></div><div className="storage"><b>{formatBytes(storage.totalBytes)}</b><span>{tr('当前占用','Current use')}</span></div></div><div className="snapshot-policy"><div><label>{tr('保留天数','Retention days')}<input type="number" min="1" value={policy.retentionDays} onChange={e=>setPolicy({...policy,retentionDays:Number(e.target.value)})}/></label><label>{tr('空间上限（GB）','Storage limit (GB)')}<input type="number" min="0.1" step="0.5" value={(policy.maxBytes/1024/1024/1024).toFixed(1)} onChange={e=>setPolicy({...policy,maxBytes:Math.round(Number(e.target.value)*1024*1024*1024)})}/></label></div><button className="primary" onClick={()=>void save()}>{tr('保存策略','Save policy')}</button></div></section>
}

function DecisionsView({project,editParrot,setNotice}:{project:ProjectRecord|null;editParrot():void;setNotice:(s:string)=>void}){
  const [items,setItems]=useState<DecisionRecord[]>([]);const [content,setContent]=useState('')
  const load=useCallback(()=>project?window.crazyParrot.decisions.list(project.id).then(setItems):Promise.resolve(),[project])
  useEffect(()=>{void load()},[load])
  if(!project)return <section className="page"><div className="empty-conversation"><h2>{tr('选择项目','Select a project')}</h2></div></section>
  const add=async()=>{if(!content.trim())return;try{await window.crazyParrot.decisions.add(project.id,content);setContent('');await load();setNotice(tr('决定已记录','Decision recorded'))}catch(e){showError(e,setNotice)}}
  return <section className="page decisions-page"><div className="page-heading"><div><div className="eyebrow">{project.name}</div><h1>{tr('决策','Decisions')}</h1></div><button onClick={editParrot}>{tr('编辑 Parrot','Edit Parrot')}</button></div><div className="decision-compose"><textarea value={content} onChange={e=>setContent(e.target.value)} placeholder={tr('记录项目决定…','Record a decision…')}/><button className="primary" onClick={()=>void add()}>{tr('记录','Add')}</button></div><div className="decision-list">{items.map(item=><article key={item.id}><span>◇</span><div><p>{item.content}</p><small>{formatTime(item.createdAt)}{item.taskId?` · ${tr('任务','Task')} ${item.taskId.slice(0,8)}`:''}</small></div><button onClick={async()=>{await window.crazyParrot.decisions.remove(item.id);await load()}}>{tr('删除','Delete')}</button></article>)}{!items.length&&<div className="empty-table">{tr('暂无记录','No decisions')}</div>}</div></section>
}

function Field({label,value,onChange,area,password}:{label:string;value:string;onChange:(v:string)=>void;area?:boolean;password?:boolean}){return <label className="field"><span>{label}</span>{area?<textarea value={value} onChange={e=>onChange(e.target.value)}/>:<input type={password?'password':'text'} value={value} onChange={e=>onChange(e.target.value)}/>}</label>}
const statusText=(s:TaskRecord['status'])=>language==='zh'?({queued:'待发送',planning:'规划中',awaiting_approval:'等待批准',running:'执行中',completed:'已完成',failed:'失败',interrupted:'可恢复',cancelled:'已停止',reverted:'已回退'}[s]):({queued:'Queued',planning:'Planning',awaiting_approval:'Awaiting approval',running:'Running',completed:'Completed',failed:'Failed',interrupted:'Recoverable',cancelled:'Stopped',reverted:'Reverted'}[s])
const formatTime=(v:string)=>new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v))
const formatBytes=(n:number)=>n<1024?`${n} B`:n<1024*1024?`${(n/1024).toFixed(1)} KB`:`${(n/1024/1024).toFixed(1)} MB`
function showError(error:unknown,setter:(v:string)=>void){
  const raw=error instanceof Error?error.message:String(error)
  const message=raw.replace(/^Error invoking remote method '[^']+':\s*Error:\s*/,'')
  if(message.includes('项目 Parrot 仍有必填项缺失')){setter(tr('项目 Parrot 仍有必填项缺失。请打开 Parrot，补齐标注的章节后再确认。','The project Parrot is incomplete. Open Parrot, complete the marked sections, then confirm it.'));return}
  setter(message)
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>)
